import gg
import rand

const win_width = 800
const win_height = 600
const width = 100
const height = 140
const scale = 4
const palette = [
	gg.rgb(0x07, 0x07, 0x07),
	gg.rgb(0x1f, 0x07, 0x07),
	gg.rgb(0x2f, 0x0f, 0x07),
	gg.rgb(0x47, 0x0f, 0x07),
	gg.rgb(0x57, 0x17, 0x07),
	gg.rgb(0x67, 0x1f, 0x07),
	gg.rgb(0x77, 0x1f, 0x07),
	gg.rgb(0x8f, 0x27, 0x07),
	gg.rgb(0x9f, 0x2f, 0x07),
	gg.rgb(0xaf, 0x3f, 0x07),
	gg.rgb(0xbf, 0x47, 0x07),
	gg.rgb(0xc7, 0x47, 0x07),
	gg.rgb(0xdf, 0x4f, 0x07),
	gg.rgb(0xdf, 0x57, 0x07),
	gg.rgb(0xdf, 0x57, 0x07),
	gg.rgb(0xd7, 0x5f, 0x07),
	gg.rgb(0xd7, 0x5f, 0x07),
	gg.rgb(0xd7, 0x67, 0x0f),
	gg.rgb(0xcf, 0x6f, 0x0f),
	gg.rgb(0xcf, 0x77, 0x0f),
	gg.rgb(0xcf, 0x7f, 0x0f),
	gg.rgb(0xcf, 0x87, 0x17),
	gg.rgb(0xc7, 0x87, 0x17),
	gg.rgb(0xc7, 0x8f, 0x17),
	gg.rgb(0xc7, 0x97, 0x1f),
	gg.rgb(0xbf, 0x9f, 0x1f),
	gg.rgb(0xbf, 0x9f, 0x1f),
	gg.rgb(0xbf, 0xa7, 0x27),
	gg.rgb(0xbf, 0xa7, 0x27),
	gg.rgb(0xbf, 0xaf, 0x2f),
	gg.rgb(0xb7, 0xaf, 0x2f),
	gg.rgb(0xb7, 0xb7, 0x2f),
	gg.rgb(0xb7, 0xb7, 0x37),
	gg.rgb(0xcf, 0xcf, 0x6f),
	gg.rgb(0xdf, 0xdf, 0x9f),
	gg.rgb(0xef, 0xef, 0xc7),
	gg.rgb(0xff, 0xff, 0xff),
]!

struct App {
mut:
	gg    &gg.Context = unsafe { nil }
	buf   [][]int
	dying bool
	tiles int
}

fn main() {
	mut app := &App{
		buf: [][]int{len: height - 1, init: []int{len: width}}
	}
	app.buf << []int{len: width, init: 36} // white fire base

	app.gg = gg.new_context(
		event_fn:     event
		frame_fn:     frame
		init_fn:      retile
		window_title: 'Fire Animation'
		user_data:    app
		bg_color:     palette[0]
		width:        win_width
		height:       win_height
	)
	app.gg.run()
}

fn retile(mut app App) {
	size := app.gg.window_size()
	app.tiles = size.width / (width * scale) + 1
}

fn (mut app App) draw() {
	size := app.gg.window_size()
	for t in 0 .. app.tiles {
		app.gg.begin()
		for y, row in app.buf {
			for x, i in row {
				app.gg.draw_square_filled(t * width * scale + x * scale,

					(size.height - height * scale) + y * scale, scale, palette[i])
			}
		}
		app.gg.end(
			how: if t == 0 { .clear } else { .passthru }
		)
		// one pass per tile to avoid sgl vertex limit
	}
}

@[direct_array_access]
fn (mut app App) tick() {
	for x in 0 .. width {
		for y in 1 .. height {
			if app.buf[y][x] > 0 {
				r := rand.intn(4) or { panic('failed to generate random number') }
				xn := ((x - r + 1) % width + width) % width
				app.buf[y - 1][xn] = app.buf[y][x] - r % 2
			} else {
				app.buf[y - 1][x] = 0
			}
		}
	}
	if app.dying {
		for x in 0 .. width {
			y := height - 1
			app.buf[y][x] -= rand.intn(4) or { panic('failed to generate random number') }
			if app.buf[y][x] < 0 {
				app.buf[y][x] = 0
			}
		}
	}
}

fn event(event &gg.Event, mut app App) {
	match event.typ {
		.key_up {
			match event.key_code {
				.space {
					if app.dying {
						app.dying = false
						app.buf[height - 1] = []int{len: width, init: 36}
					} else {
						app.dying = true
					}
				}
				else {}
			}
		}
		.resized {
			retile(mut app)
		}
		else {}
	}
}

fn frame(mut app App) {
	app.draw()
	app.tick()
}

module main

import gg
import sokol.sgl

struct App {
mut:
	gg &gg.Context = unsafe { nil }
}

const cmax_x = 115
const cmax_y = 81
const cs = 10

const c_fg = gg.rgb(20, 30, 255)

fn main() {
	mut app := &App{}
	app.gg = gg.new_context(
		bg_color:      gg.white
		width:         cmax_x * cs
		height:        cmax_y * cs
		create_window: true
		window_title:  'Grid with many rectangles (drawn with no context)'
		frame_fn:      frame
		user_data:     app
	)
	app.gg.run()
}

fn frame(app &App) {
	app.gg.begin()
	// Note: this uses 2 separate loops, with each doing its own drawing for performance reasons.
	// The underlying Sokol library can eliminate sgl begin/end calls, when multiple primitives of the
	// same kind are drawn one after the other, without context changes.
	// However, filled rectangles are drawn with quads, while empty rectangles are drawn with lines.
	// In this case, if the draw calls are put in the same loop, using app.gg.draw_rect_filled/5 and app.gg.draw_rect_empty/5,
	// sokol can not batch the begin/end calls, and their overhead becomes much bigger.
	//
	// That is why:
	// a) we use several loops here.
	// b) we use a single sgl.begin_quads() before the first loop, and a single sgl.end() after it.
	// c) we use draw_rect_filled_no_context/5 inside the loop, instead of draw_rect_filled/5 .
	// e) we use a single sgl.begin_lines() before the second loop, and a single sgl.end() after it.
	// f) we use draw_rect_empty_no_context/5 inside the second loop, instead of draw_rect_empty/5 .
	// Note: the separation of the loops/kinds of draws, is several times more important for eliminating
	// the performance overhead (12-15% CPU usage), compared to the use of draw_rect_filled_no_context
	// vs draw_rect_filled (1-2% CPU usage), because of Sokol's optimisation.

	$if !do_not_draw_rect_filled ? {
		sgl.begin_quads()
		for y in 0 .. cmax_y {
			for x in 0 .. cmax_x {
				cy, cx := y * cs, x * cs
				app.gg.draw_rect_filled_no_context(cx, cy, cs - 2, cs - 2, c_fg)
			}
		}
		sgl.end()
	}

	$if draw_rect_empty ? {
		sgl.begin_lines()
		for y in 0 .. cmax_y {
			for x in 0 .. cmax_x {
				cy, cx := y * cs, x * cs
				app.gg.draw_rect_empty_no_context(cx + 2, cy + 2, cs - 3, cs - 3,
					gg.rgb(255, 50, 0))
			}
		}
		sgl.end()
	}

	app.gg.end()
}

module main

import gg
import rand

const max_circles_per_pass = 1000

// prepare some random colors ahead of time
const colors = []gg.Color{len: max_circles_per_pass, init: gg.Color{
	r: u8(index * 0 + rand.u8())
	g: u8(index * 0 + rand.u8())
	b: u8(index * 0 + rand.u8())
}}

fn frame(mut ctx gg.Context) {
	// First pass, just clears the background:
	ctx.begin()
	ctx.end()

	// We want to draw thousands of circles, but sokol has a limit for how
	// many primitives can be in a single pass, and if you reach that limit
	// you will not see *anything at all* for that pass.
	// For the circles below, that limit is ~2520 circles per pass.
	// To overcome this, we will use several passes instead, where each one
	// will draw just 1000 circles.
	// In other words, in total we will have 4 * 1000 = 4000 circles, drawn with
	// 4 passes.
	for i := 0; i < 4 * max_circles_per_pass; i += max_circles_per_pass {
		ctx.begin()
		for c in 0 .. max_circles_per_pass {
			rx := rand.int_in_range(0, ctx.window.width) or { 0 }
			ry := rand.int_in_range(0, ctx.window.height) or { 0 }
			ctx.draw_circle_filled(rx, ry, 10, colors[c])
		}
		ctx.end(how: .passthru)
	}

	// The last pass, is for the fps overlay, that should be *always on top of everything*.
	// Drawing it in a separate pass, guarantees, that it *will* be drawn, even if the drawing
	// of all the other passes fail. Try increasing max_circles_per_pass to 3000 for example.
	ctx.begin()
	ctx.show_fps()
	ctx.end(how: .passthru)
}

fn main() {
	mut ctx := gg.new_context(
		window_title: 'Many Thousands of Circles'
		bg_color:     gg.black
		width:        600
		height:       400
		frame_fn:     frame
	)
	ctx.run()
}

