module main

import gg
import rand
import time

const cover = gg.rgba(85, 200, 85, 255)
const csize = 120 // cell size in pixels
const letters = 'AABBOOCCVVXXYYZZMMKKHHTT'.split('')
const header_size = 30

struct Cell {
mut:
	is_open bool
	letter  string
}

struct Game {
mut:
	ctx       &gg.Context = unsafe { nil }
	cells     []Cell
	card1_idx ?int
	card2_idx ?int
	size      int // in cells
	remaining int
	sw        time.StopWatch = time.new_stopwatch()
	revert_sw time.StopWatch = time.new_stopwatch(auto_start: false)
}

fn (mut g Game) restart() {
	ncells := g.size * g.size
	g.remaining = ncells
	g.cells = []Cell{len: ncells, init: Cell{
		letter: letters[index % letters.len]
	}}
	rand.shuffle(mut g.cells) or {}
	g.sw = time.new_stopwatch()
	g.card1_idx = none
	g.card2_idx = none
}

fn (mut g Game) draw_cell(i int) {
	x, y := i % g.size, i / g.size
	rect_x, rect_y := x * csize, header_size + y * csize
	if g.cells[i].is_open || g.sw.elapsed().milliseconds() <= 1000 {
		lsize := 96
		g.ctx.draw_rect_empty(rect_x + 6, rect_y + 6, csize - 10, csize - 10, gg.light_gray)
		g.ctx.draw_text(rect_x + csize / 2 - lsize / 3, rect_y + csize / 2 - lsize / 2,
			g.cells[i].letter,
			color: gg.yellow
			size:  lsize
		)
	} else {
		g.ctx.draw_rect_filled(rect_x + 6, rect_y + 6, csize - 10, csize - 10, cover)
	}
}

fn on_frame(mut g Game) {
	ws := gg.window_size()
	g.ctx.begin()
	message := '(r)estart (esc)ape | remaining: ${g.remaining:02} | time: ${f64(g.sw.elapsed().milliseconds()) / 1000.0:06.1f}s'
	g.ctx.draw_text(ws.width / 2, 7, message, color: gg.light_gray, size: 22, align: .center)
	for i in 0 .. g.cells.len {
		g.draw_cell(i)
	}
	if g.revert_sw.elapsed().milliseconds() > 750 {
		g.revert_sw = time.new_stopwatch(auto_start: false)
		if g.card1_idx != none {
			if g.card2_idx != none {
				g.cells[g.card1_idx].is_open = false
				g.cells[g.card2_idx].is_open = false
				g.card1_idx = none
				g.card2_idx = none
				g.remaining = g.cells.count(!it.is_open)
			}
		}
	}
	g.ctx.end()
}

fn on_event(e &gg.Event, mut g Game) {
	if e.typ == .key_down {
		match e.key_code {
			.escape { g.ctx.quit() }
			.r { g.restart() }
			else {}
		}

		return
	}
	if e.typ != .mouse_down {
		return
	}
	x, y := int(e.mouse_x / csize), int((e.mouse_y - header_size) / csize)
	if e.mouse_button == .left && g.card2_idx == none {
		if g.remaining == 0 {
			g.restart()
			return
		}
		i := y * g.size + x
		if !g.cells[i].is_open {
			g.cells[i].is_open = true
			if g.card1_idx == none {
				g.card1_idx = i
			} else {
				g.card2_idx = i
				if g.cells[g.card1_idx].letter == g.cells[i].letter {
					g.card1_idx = none
					g.card2_idx = none
				} else {
					// start a timer, that will be checked in the on_frame callback
					g.revert_sw.start()
				}
			}
		}
	}
	g.remaining = g.cells.count(!it.is_open)
	if g.remaining == 0 {
		g.sw.stop()
	}
}

mut g := &Game{
	// the CLI argument should be number of pairs, so `size` is even, and the puzzle can be solved:
	size: arguments()[1] or { '3' }.int() * 2
}
g.restart()
g.ctx = gg.new_context(
	bg_color:     gg.black
	width:        g.size * csize
	height:       header_size + g.size * csize
	window_title: 'V Memory ${g.size} x ${g.size}'
	user_data:    g
	frame_fn:     on_frame
	event_fn:     on_event
	sample_count: 2
)
g.ctx.run()

module main

import gg
import rand
import os.asset

const header_size = 30

enum Cell {
	empty
	n1
	n2
	n3
	n4
	n5
	n6
	n7
	n8
	mine
}

@[heap]
struct Game {
mut:
	ctx           &gg.Context = unsafe { nil }
	grid          [][]Cell
	flags         [][]bool
	revealed      [][]bool
	size          int = 10 // in cells
	csize         int = 30 // in pixels
	game_over     bool
	first_click   bool = true
	mines         int  = 10
	mines_flagged int
}

@[inline]
fn (mut g Game) in_grid(cy int, cx int) bool {
	return cx >= 0 && cx < g.size && cy >= 0 && cy < g.size
}

fn (mut g Game) generate_mines(first_y int, first_x int) {
	mut mines_placed := 0
	for mines_placed < g.mines {
		x, y := rand.intn(g.size) or { 0 }, rand.intn(g.size) or { 0 }
		// avoid placing mines at the position of the first click
		if (x == first_x && y == first_y) || g.grid[y][x] == .mine {
			continue
		}
		g.grid[y][x] = .mine
		mines_placed++
	}
	for y in 0 .. g.size {
		for x in 0 .. g.size {
			if g.grid[y][x] == .mine {
				continue
			}
			mut count := 0
			for dy in -1 .. 2 {
				for dx in -1 .. 2 {
					cy, cx := y + dy, x + dx
					if g.in_grid(cy, cx) {
						if g.grid[cy][cx] == .mine {
							count++
						}
					}
				}
			}
			g.grid[y][x] = unsafe { Cell(count) }
		}
	}
}

fn (mut g Game) reveal(y int, x int) {
	if !g.in_grid(y, x) {
		return
	}
	if g.revealed[y][x] {
		return
	}
	g.revealed[y][x] = true
	if g.grid[y][x] == .mine {
		g.game_over = true
		return
	}
	if g.grid[y][x] == .empty {
		for dy in -1 .. 2 {
			for dx in -1 .. 2 {
				g.reveal(y + dy, x + dx)
			}
		}
	}
}

fn (mut g Game) restart() {
	g.grid = [][]Cell{len: g.size, init: []Cell{len: g.size}}
	g.flags = [][]bool{len: g.size, init: []bool{len: g.size}}
	g.revealed = [][]bool{len: g.size, init: []bool{len: g.size}}
	g.game_over = false
	g.first_click = true
	g.mines_flagged = 0
}

fn on_event(e &gg.Event, mut g Game) {
	if e.typ == .key_down {
		match e.key_code {
			.escape { g.ctx.quit() }
			.r { g.restart() }
			else {}
		}

		return
	}
	if g.game_over {
		return
	}
	if e.typ != .mouse_down {
		return
	}
	x := int(e.mouse_x / g.csize)
	y := int((e.mouse_y - header_size) / g.csize)
	if e.mouse_button == .left {
		if g.first_click {
			g.generate_mines(y, x)
			g.first_click = false
		}
		g.reveal(y, x)
	}
	if e.mouse_button == .right {
		if !g.revealed[y][x] {
			old := g.flags[y][x]
			g.flags[y][x] = !old
			g.mines_flagged += if old { -1 } else { 1 }
		}
	}
	if e.mouse_button == .middle {
		if g.revealed[y][x] {
			count := g.act_on_neighbors(y, x, fn (mut g Game, cy int, cx int) int {
				if g.in_grid(cy, cx) {
					return int(g.flags[cy][cx])
				}
				return 0
			})
			if int(g.grid[y][x]) == count {
				g.act_on_neighbors(y, x, fn (mut g Game, cy int, cx int) int {
					if g.in_grid(cy, cx) && !g.flags[cy][cx] {
						g.reveal(cy, cx)
					}
					return 0
				})
			}
		}
	}
}

fn (mut g Game) act_on_neighbors(y int, x int, f fn (mut g Game, cy int, cx int) int) int {
	mut count := 0
	for dy in -1 .. 2 {
		for dx in -1 .. 2 {
			if dy == 0 && dx == 0 {
				continue
			}
			cy, cx := y + dy, x + dx
			count += f(mut g, cy, cx)
		}
	}
	return count
}

fn (mut g Game) draw_cell(y int, x int) {
	o := header_size
	rect_x, rect_y := x * g.csize, y * g.csize
	if g.revealed[y][x] {
		if g.grid[y][x] == .mine {
			g.ctx.draw_rect_filled(rect_x, o + rect_y, g.csize, g.csize, gg.red)
			g.ctx.draw_text(rect_x + 10, o + rect_y + 5, '*', color: gg.black)
		} else if int(g.grid[y][x]) > 0 {
			g.ctx.draw_rect_filled(rect_x, o + rect_y, g.csize, g.csize, gg.light_gray)
			n := int(g.grid[y][x]).str()
			g.ctx.draw_text(rect_x + 10, o + rect_y + 5, n, color: gg.black)
		} else {
			c := gg.rgb(240, 240, 240)
			g.ctx.draw_rect_filled(rect_x, o + rect_y, g.csize, g.csize, c)
		}
	} else if g.flags[y][x] {
		g.ctx.draw_rect_filled(rect_x, o + rect_y, g.csize, g.csize, gg.gray)
		g.ctx.draw_text(rect_x + 10, o + rect_y + 5, 'F', color: gg.white)
	} else {
		g.ctx.draw_rect_filled(rect_x, o + rect_y, g.csize, g.csize, gg.gray)
	}
	g.ctx.draw_rect_empty(rect_x, o + rect_y, g.csize, g.csize, gg.black)
}

fn on_frame(mut g Game) {
	g.ctx.begin()
	for y in 0 .. g.size {
		for x in 0 .. g.size {
			g.draw_cell(y, x)
		}
	}
	message := 'Flagged: ${g.mines_flagged:02}/${g.mines:02}         (r)estart (ESC)ape'
	g.ctx.draw_text(5, 7, message, color: gg.green)
	g.ctx.end()
}

fn main() {
	mut g := &Game{}
	g.restart()
	g.ctx = gg.new_context(
		bg_color:     gg.black
		width:        g.size * g.csize
		height:       header_size + g.size * g.csize
		window_title: 'V Minesweeper'
		user_data:    g
		frame_fn:     on_frame
		event_fn:     on_event
		font_path:    asset.get_path('../assets', 'fonts/RobotoMono-Regular.ttf')
	)
	g.ctx.run()
}

