fn maybe_begin_client_chrome_action(event gg.WindowInputEvent, mut app gg.App, caps gg.Capabilities, native_decorations bool) !string {
	if !client_chrome_enabled(caps, native_decorations) {
		return ''
	}
	input := event.event
	if input.typ != .mouse_down || input.mouse_button != .left {
		return ''
	}
	if close_button_hit_at(input.mouse_x, input.mouse_y, input.window_width, input.window_height) {
		app.destroy_window(event.window)!
		return '${event.window}: client chrome close button destroyed window'
	}
	inactive_control := inactive_client_chrome_control_hit_at(input.mouse_x, input.mouse_y,
		input.window_width, input.window_height)
	if inactive_control {
		return ''
	}
	if edge := resize_edge_at(input.mouse_x, input.mouse_y, input.window_width, input.window_height) {
		app.begin_window_resize(event.window, edge)!
		return '${event.window}: interactive resize ${edge} started'
	}
	if move_hit_at(input.mouse_x, input.mouse_y, input.window_width, input.window_height) {
		app.begin_window_move(event.window)!
		return '${event.window}: interactive move started'
	}
	return ''
}

fn update_dashboard_cursor(event gg.WindowInputEvent, mut app gg.App, caps gg.Capabilities, native_decorations bool, hovered_control DashboardControl) ! {
	if !caps.cursor_shapes {
		return
	}
	input := event.event
	match input.typ {
		.mouse_leave {
			app.set_window_cursor(event.window, .default)!
		}
		.mouse_enter, .mouse_move {
			shape := if hovered_control != .inactive {
				gg.WindowCursorShape.pointer
			} else if client_chrome_enabled(caps, native_decorations) {
				client_chrome_cursor_shape_at(input.mouse_x, input.mouse_y, input.window_width,
					input.window_height)
			} else {
				gg.WindowCursorShape.default
			}
			app.set_window_cursor(event.window, shape)!
		}
		else {}
	}
}

fn client_chrome_cursor_shape_at(x f32, y f32, width int, height int) gg.WindowCursorShape {
	if close_button_hit_at(x, y, width, height) {
		return .pointer
	}
	if inactive_client_chrome_control_hit_at(x, y, width, height) {
		return .default
	}
	if edge := resize_edge_at(x, y, width, height) {
		return cursor_shape_for_resize_edge(edge)
	}
	if move_hit_at(x, y, width, height) {
		return .move
	}
	return .default
}

fn cursor_shape_for_resize_edge(edge gg.WindowResizeEdge) gg.WindowCursorShape {
	return match edge {
		.top, .bottom { .ns_resize }
		.left, .right { .ew_resize }
		.top_left, .bottom_right { .nwse_resize }
		.top_right, .bottom_left { .nesw_resize }
	}
}

fn client_chrome_enabled(caps gg.Capabilities, native_decorations bool) bool {
	return caps.wayland && caps.interactive_move_resize && !native_decorations
}

fn move_hit_at(x f32, y f32, width int, height int) bool {
	if width <= 2 * client_chrome_resize_margin || height <= client_chrome_titlebar_height {
		return false
	}
	if client_chrome_titlebar_control_hit_at(x, y, width, height) {
		return false
	}
	return x > f32(client_chrome_resize_margin) && x < f32(width - client_chrome_resize_margin)
		&& y >= 0 && y <= f32(client_chrome_titlebar_height)
}

fn inactive_client_chrome_control_hit_at(x f32, y f32, width int, height int) bool {
	return window_control_button_hit_at(x, y, width, height, 1)
		|| window_control_button_hit_at(x, y, width, height, 2)
}

fn client_chrome_titlebar_control_hit_at(x f32, y f32, width int, height int) bool {
	return close_button_hit_at(x, y, width, height)
		|| inactive_client_chrome_control_hit_at(x, y, width, height)
}

fn close_button_hit_at(x f32, y f32, width int, height int) bool {
	return window_control_button_hit_at(x, y, width, height, 0)
}

fn window_control_button_hit_at(x f32, y f32, width int, height int, index_from_right int) bool {
	if width <= 0 || height <= client_chrome_titlebar_height {
		return false
	}
	button_x := window_control_button_x(width, index_from_right)
	button_y := close_button_y()
	button_size := f32(client_chrome_close_button_size)
	return x >= button_x && x <= button_x + button_size && y >= button_y
		&& y <= button_y + button_size
}

fn close_button_x(width int) f32 {
	return window_control_button_x(width, 0)
}

fn window_control_button_x(width int, index_from_right int) f32 {
	step := client_chrome_close_button_size + client_chrome_control_gap
	return f32(width - client_chrome_close_button_margin - client_chrome_close_button_size -
		index_from_right * step)
}

fn close_button_y() f32 {
	return f32((client_chrome_titlebar_height - client_chrome_close_button_size) / 2)
}

fn resize_edge_at(x f32, y f32, width int, height int) ?gg.WindowResizeEdge {
	if width <= 0 || height <= 0 {
		return none
	}
	margin := f32(client_chrome_resize_margin)
	w := f32(width)
	h := f32(height)
	near_left := x >= 0 && x <= margin
	near_right := x >= w - margin && x <= w
	near_top := y >= 0 && y <= margin
	near_bottom := y >= h - margin && y <= h
	if near_top && near_left {
		return gg.WindowResizeEdge.top_left
	}
	if near_top && near_right {
		return gg.WindowResizeEdge.top_right
	}
	if near_top {
		return gg.WindowResizeEdge.top
	}
	if near_bottom && near_left {
		return gg.WindowResizeEdge.bottom_left
	}
	if near_bottom && near_right {
		return gg.WindowResizeEdge.bottom_right
	}
	if near_bottom {
		return gg.WindowResizeEdge.bottom
	}
	if near_left {
		return gg.WindowResizeEdge.left
	}
	if near_right {
		return gg.WindowResizeEdge.right
	}
	return none
}

fn resize_or_ignore_unsupported(mut app gg.App, window gg.WindowId, width int, height int) ! {
	app.resize_window(window, width, height) or {
		if err.msg() == 'multiwindow: backend capability is unsupported' {
			return
		}
		return err
	}
}

module main

import gg
import sokol.gfx
import time
import gg.testdata.multiwindow_probe_backend
import gg.testdata.multiwindow_probe_gate

const render_probe_watchdog = 5 * time.second

struct RenderProbeFrameSignal {
	window string
	serial u64
}

struct RenderProbeState {
mut:
	frames            map[string]u64
	cleanup_submitted map[string]u64
}

fn main() {
	run_render_probe() or { panic(err) }
}

fn run_render_probe() ! {
	multiwindow_probe_gate.await_parent_release(render_probe_watchdog)!
	frames := chan RenderProbeFrameSignal{cap: 8}
	driver_result := chan string{cap: 1}
	mut state := &RenderProbeState{}
	backend := multiwindow_probe_backend.selected()!
	mut app := gg.new_app(
		backend:          backend
		queue_size:       16
		require_renderer: true
	)!
	multiwindow_probe_backend.validate(app.capabilities(), backend)!

	main_window := app.create_window(
		title:       'gg runtime probe: main'
		width:       640
		height:      400
		clear_color: gg.rgb(18, 28, 38)
		redraw_mode: .on_demand
		frame_fn:    fn [frames, mut state] (mut context gg.WindowContext) ! {
			draw_probe_window(mut context, gg.rgb(65, 170, 210), frames, mut state)!
		}
		cleanup_fn:  fn [mut state] (mut context gg.WindowCleanupContext) ! {
			state.cleanup_submitted[context.window_id().str()] = context.metrics().submitted_frame
		}
	)!
	tool_window := app.create_window(
		title:       'gg runtime probe: tool'
		width:       360
		height:      260
		clear_color: gg.rgb(236, 224, 196)
		redraw_mode: .on_demand
		frame_fn:    fn [frames, mut state] (mut context gg.WindowContext) ! {
			draw_probe_window(mut context, gg.rgb(205, 82, 55), frames, mut state)!
		}
		cleanup_fn:  fn [mut state] (mut context gg.WindowCleanupContext) ! {
			state.cleanup_submitted[context.window_id().str()] = context.metrics().submitted_frame
		}
	)!

	driver := spawn drive_render_probe(mut app, main_window, tool_window, frames, driver_result)
	mut run_error := ''
	app.run(
		event_fn: fn (event gg.WindowEvent, mut app gg.App) ! {
			if event.kind != .window_close_requested || !app.window_exists(event.window) {
				return
			}
			app.destroy_window(event.window)!
			if app.window_ids()!.len == 0 {
				app.stop()!
			}
		}
	) or { run_error = err.msg() }
	driver.wait()
	driver_error := <-driver_result
	mut stop_error := ''
	app.stop() or { stop_error = err.msg() }

	mut failures := []string{}
	if run_error != '' {
		failures << 'owner loop: ${run_error}'
	}
	if driver_error != '' {
		failures << 'driver: ${driver_error}'
	}
	if stop_error != '' {
		failures << 'final stop: ${stop_error}'
	}
	if failures.len > 0 {
		return error(failures.join('; '))
	}
	for window in [main_window, tool_window] {
		key := window.str()
		assert state.frames[key] >= 2, '${key} did not cross both frame barriers'
		assert state.cleanup_submitted[key] == state.frames[key], '${key} cleanup observed ${state.cleanup_submitted[key]} submitted frames after ${state.frames[key]} successful callbacks'
	}
	println('{"example":"multiwindow_render_runtime","status":"PASS","cleanup":"complete"}')
}

fn drive_render_probe(mut app gg.App, main_window gg.WindowId, tool_window gg.WindowId, frames chan RenderProbeFrameSignal, result chan string) {
	windows := [main_window.str(), tool_window.str()]
	first := wait_for_render_probe_barrier(frames, windows, map[string]u64{}) or {
		fail_render_probe(mut app, 'first frame barrier: ${err.msg()}', result)
		return
	}
	app.request_redraw(main_window) or {
		fail_render_probe(mut app, 'main redraw admission: ${err.msg()}', result)
		return
	}
	app.request_redraw(main_window) or {
		fail_render_probe(mut app, 'coalesced main redraw admission: ${err.msg()}', result)
		return
	}
	app.request_redraw(tool_window) or {
		fail_render_probe(mut app, 'tool redraw admission: ${err.msg()}', result)
		return
	}
	wait_for_render_probe_barrier(frames, windows, first) or {
		fail_render_probe(mut app, 'second frame barrier: ${err.msg()}', result)
		return
	}
	post_render_probe_stop(mut app) or {
		result <- 'owner stop admission: ${err.msg()}'
		return
	}
	result <- ''
}

fn wait_for_render_probe_barrier(frames chan RenderProbeFrameSignal, windows []string, after map[string]u64) !map[string]u64 {
	mut seen := map[string]u64{}
	for seen.len < windows.len {
		select {
			signal := <-frames {
				if signal.window !in windows || signal.serial <= after[signal.window] {
					continue
				}
				seen[signal.window] = signal.serial
			}
			render_probe_watchdog {
				return error('watchdog expired with ${seen.len}/${windows.len} windows ready')
			}
		}
	}
	return seen
}

fn fail_render_probe(mut app gg.App, message string, result chan string) {
	post_render_probe_stop(mut app) or {
		result <- '${message}; owner stop admission failed: ${err.msg()}'
		return
	}
	result <- message
}

fn post_render_probe_stop(mut app gg.App) ! {
	app.post(fn (mut app gg.App) ! {
		app.stop()!
	})!
}

fn draw_probe_window(mut context gg.WindowContext, accent gg.Color, frames chan RenderProbeFrameSignal, mut state RenderProbeState) ! {
	info := context.frame_info()
	assert info.frame_serial == info.submitted_frame + 1
	assert info.metrics.submitted_frame == info.submitted_frame
	assert info.metrics.logical_size.width > 0
	assert info.metrics.logical_size.height > 0
	assert info.metrics.framebuffer_size.width > 0
	assert info.metrics.framebuffer_size.height > 0
	action := gfx.create_clear_pass_action(0, 0, 0, 0)
	context.with_swapchain_sgl(action, fn [info, accent] (mut drawing gg.WindowSglContext) ! {
		width := info.metrics.logical_size.width
		height := info.metrics.logical_size.height
		drawing.defaults()
		drawing.matrix_mode_projection()
		drawing.load_identity()
		drawing.ortho(0, width, height, 0, -1, 1)
		drawing.c4b(accent.r, accent.g, accent.b, accent.a)
		drawing.begin_quads()
		drawing.v2f(width * 0.15, height * 0.2)
		drawing.v2f(width * 0.85, height * 0.2)
		drawing.v2f(width * 0.85, height * 0.8)
		drawing.v2f(width * 0.15, height * 0.8)
		drawing.end()
	})!
	state.frames[info.window.str()]++
	frames <- RenderProbeFrameSignal{
		window: info.window.str()
		serial: info.frame_serial
	}
}

// Run with `v -d gg_multiwindow run examples/gg/multiwindow_services.v`.
// Add `-d x_multiwindow_x11` or `-d sokol_wayland` on Linux to enable that
// native backend. The capability checks also make the mock fallback useful.
module main

import gg

struct ServiceExampleState {
	backend gg.MultiWindowBackend
	mock    bool
mut:
	pending           int
	clipboard_request ?gg.ClipboardRequestId
	portal_request    ?gg.PortalParentRequestId
	readback_request  ?gg.WindowReadbackId
	completed         map[string]bool
}

fn main() {
	run_services_example() or {
		eprintln('multi-window services example failed: ${err.msg()}')
		exit(1)
	}
}

fn run_services_example() ! {
	mut app := gg.new_app(
		backend: .auto
		app_id:  'org.vlang.gg.multiwindow-services'
	)!
	defer {
		app.stop() or {}
	}

	window := app.create_window(
		title:   'GG multi-window services'
		width:   640
		height:  360
		visible: false
	)!
	caps := app.capabilities()
	mut state := &ServiceExampleState{
		backend: caps.backend
		mock:    caps.mock
	}
	println('backend=${caps.backend} native=${caps.native} readback=${caps.readback}')

	window_state := app.window_state(window)!
	println('window mapping=${window_state.mapping} visibility=${window_state.visibility}')
	for monitor_id in app.monitor_ids()! {
		monitor := app.monitor_info(monitor_id)!
		println('monitor ${monitor.id}: ${monitor.name} available=${monitor.available} scale_known=${monitor.scale.known}')
	}

	show_capability := app.window_operation_capability(window, .show)!
	println('show support=${show_capability.support} async=${show_capability.asynchronous}')
	if show_capability.support != .unsupported {
		app.show_window(window) or { eprintln('show request rejected: ${err.msg()}') }
	}
	inspect_native_window(mut app, window) or {
		eprintln('native borrow unavailable at runtime: ${err.msg()}')
	}
	request_clipboard(mut app, window, mut state)!
	request_portal_parent(mut app, window, mut state)!
	request_optional_readback(mut app, window, mut state)!

	if state.mock && state.pending == 0 {
		app.post(fn (mut app gg.App) ! {
			app.stop()!
		})!
	}

	app.run(
		event_fn:          fn (event gg.WindowEvent, mut app gg.App) ! {
			match event.kind {
				.window_close_requested {
					app.destroy_window(event.window)!
				}
				.window_destroyed {
					if app.window_ids()!.len == 0 {
						app.stop()!
					}
				}
				else {}
			}
		}
		input_fn:          fn (event gg.WindowInputEvent, mut _ gg.App) ! {
			println('input window=${event.window} kind=${event.event.typ}')
		}
		window_service_fn: fn [mut state] (event gg.WindowServiceEvent, mut app gg.App) ! {
			match event.kind {
				.clipboard {
					if !state.matches_clipboard(event.clipboard.id) {
						return
					}
					println('clipboard ${event.clipboard.id}: ${event.clipboard.status}')
					stop_example_if_complete(mut app, state.complete_one('clipboard'))
				}
				.portal_parent {
					if !state.matches_portal(event.portal_parent.id) {
						return
					}
					println('portal ${event.portal_parent.id}: ${event.portal_parent.status} ${event.portal_parent.identifier}')
					if event.portal_parent.status == .ready {
						release_portal_parent_bounded(mut app, event.portal_parent.lease)
					}
					// No fallible operation is propagated after the bounded release. Marking
					// the correlated event makes an unexpected replay idempotent.
					stop_example_if_complete(mut app, state.complete_one('portal'))
				}
				.state {
					println('state operation=${event.operation} mapping=${event.state.mapping} visibility=${event.state.visibility}')
				}
				.monitor {
					println('monitor membership changed: ${event.monitors.len} available')
				}
				else {}
			}
		}
		readback_fn:       fn [mut state] (result gg.WindowReadbackResult, mut app gg.App) ! {
			if !state.matches_readback(result.id) {
				return
			}
			println('readback status=${result.status} size=${result.width}x${result.height} stride=${result.stride}')
			stop_example_if_complete(mut app, state.complete_one('readback'))
		}
	)!
}

fn request_clipboard(mut app gg.App, window gg.WindowId, mut state ServiceExampleState) ! {
	capability := app.window_operation_capability(window, .clipboard_read)!
	println('clipboard_read support=${capability.support} async=${capability.asynchronous}')
	if capability.support == .unsupported {
		return
	}
	request := app.request_clipboard_text(window) or {
		eprintln('clipboard request rejected: ${err.msg()}')
		return
	}
	state.clipboard_request = request
	state.pending++
	println('clipboard request accepted: ${request}')
}

fn request_portal_parent(mut app gg.App, window gg.WindowId, mut state ServiceExampleState) ! {
	capability := app.window_operation_capability(window, .portal_parent)!
	println('portal_parent support=${capability.support} async=${capability.asynchronous}')
	if capability.support == .unsupported {
		return
	}
	request := app.request_portal_parent(window) or {
		eprintln('portal-parent request rejected: ${err.msg()}')
		return
	}
	state.portal_request = request
	state.pending++
	println('portal-parent request accepted: ${request}')
}

fn request_optional_readback(mut app gg.App, window gg.WindowId, mut state ServiceExampleState) ! {
	capabilities := app.window_readback_capabilities(window) or {
		eprintln('readback capability query failed: ${err.msg()}')
		return
	}
	println('readback image=${capabilities.offscreen_image} window=${capabilities.window_capture}')
	if !capabilities.window_capture {
		return
	}
	request := app.request_window_capture(window, gg.WindowReadbackConfig{}) or {
		eprintln('window capture request rejected: ${err.msg()}')
		return
	}
	state.readback_request = request
	state.pending++
	println('window capture accepted: ${request}')
}

fn inspect_native_window(mut app gg.App, window gg.WindowId) ! {
	capability := app.window_operation_capability(window, .native_borrow)!
	println('native_borrow support=${capability.support}')
	if capability.support == .unsupported {
		return
	}
	backend := app.capabilities().backend
	app.with_native_window(window, fn [backend] (mut lease gg.NativeWindowLease) ! {
		match backend {
			.win32 {
				lease.with_win32(fn (hwnd voidptr) ! {
					println('borrowed HWND=${usize(hwnd):x}')
				})!
			}
			.appkit {
				lease.with_appkit(fn (ns_window voidptr) ! {
					println('borrowed NSWindow=${usize(ns_window):x}')
				})!
			}
			.x11 {
				lease.with_x11(fn (display voidptr, xwindow u64) ! {
					println('borrowed Display=${usize(display):x} Window=${xwindow:x}')
				})!
			}
			.wayland {
				lease.with_wayland(fn (display voidptr, surface voidptr) ! {
					println('borrowed wl_display=${usize(display):x} wl_surface=${usize(surface):x}')
				})!
			}
			.auto, .mock {}
		}
	})!
}

fn (state &ServiceExampleState) matches_clipboard(id gg.ClipboardRequestId) bool {
	expected := state.clipboard_request or { return false }
	return expected == id && !state.completed['clipboard']
}

fn (state &ServiceExampleState) matches_portal(id gg.PortalParentRequestId) bool {
	expected := state.portal_request or { return false }
	return expected == id && !state.completed['portal']
}

fn (state &ServiceExampleState) matches_readback(id gg.WindowReadbackId) bool {
	expected := state.readback_request or { return false }
	return expected == id && !state.completed['readback']
}

fn release_portal_parent_bounded(mut app gg.App, lease gg.PortalParentLeaseId) {
	app.release_portal_parent(lease) or {
		if err.msg().contains('service request is stale') || err.msg().contains('app is stopped') {
			eprintln('portal-parent lease was already invalidated by teardown: ${err.msg()}')
		} else {
			eprintln('portal-parent lease release failed: ${err.msg()}')
		}
	}
}

fn (mut state ServiceExampleState) complete_one(kind string) bool {
	if state.completed[kind] {
		return false
	}
	state.completed[kind] = true
	if state.pending > 0 {
		state.pending--
	}
	return state.mock && state.pending == 0
}

fn stop_example_if_complete(mut app gg.App, complete bool) {
	if complete {
		app.stop() or {
			eprintln('example stop failed after acknowledged terminal event: ${err.msg()}')
		}
	}
}

module main

import gg // actual graphics lib
import math // for math related function

const window_width = 800
const window_height = 800
const nrows = 50

// app struct that has property of current windows
struct App {
mut:
	gg    &gg.Context = unsafe { nil }
	ui    Ui
	grid  [][]Cell
	start Point // start point of algorithm
	end   Point // end point or target point
}

// this needed to get the width and mouse position part of gg window
struct Ui {
mut:
	dpi_scale f32
}

// struct for a point
struct Point {
mut:
	x int
	y int
}

/*
RED -> Closed
GREEN -> Open
BLACK -> Barrier
WHITE -> Empty
ORANGE -> Start
TURQOIISE -> End
PINK -> Path
*/

// struct for a cell of grid
struct Cell {
mut:
	row       int
	col       int
	width     int
	pos       Point
	color     gg.Color
	flag      int // 0->empty, 1-> closed, 2-> open, 3-> barrier, 4-> start, 5-> end, 6-> path
	neighbors []Point
}

// this is a node for priority queue

struct Node {
mut:
	f_score int
	cell    Point
	count   int
}

// Min heap or priority queue

struct MinHeap {
mut:
	data []Node
}

// main function
fn main() {
	// app variable
	mut app := &App{}

	// setting values of app
	app.gg = gg.new_context(
		bg_color:      gg.black                              // background color
		width:         window_width                          // window width
		height:        window_height                         // window height
		create_window: true                                  // this will create a different window
		window_title:  'A* Path finding algorithm visusalizer' // title of the window
		frame_fn:      frame    // this is frame function update the frame
		event_fn:      on_event // it calls on every event
		user_data:     app      // store user data
	)
	mut grid :=
		initialise_grid() // initialize the grid variable and populate the matrix with each cell as empty
	app.grid = grid // set grid to app attribute so you can access it by just passing app variable or with method of app
	app.ui.dpi_scale = 1.0 // set scale this is use to make it responsive
	app.start = &Point{ // set start point to -1, -1
		x: -1
		y: -1
	}
	app.end = &Point{ // set end point to -1, -1
		x: -1
		y: -1
	}
	app.gg.run() // run the app loop
}

// this function will run for every frame actually in a loop
fn frame(mut app App) {
	app.gg.begin()
	draw_grid(mut app)
	draw_gridlines(mut app)
	app.gg.end()
}

// this will handle user event which is stored in gg.event variable
fn on_event(event &gg.Event, mut app App) {
	match event.typ {
		.mouse_down {
			x := int(event.mouse_x / app.ui.dpi_scale)
			y := int(event.mouse_y / app.ui.dpi_scale)
			btn := event.mouse_button
			app.handle_mouse_event(x, y, btn)
		}
		.key_down {
			app.on_key_down(event.key_code)
		}
		else {}
	}
}

// handle mouse event to make a cell either start  point end point or barrier or to clear
fn (mut app App) handle_mouse_event(x int, y int, btn_type gg.MouseButton) {
	gap := window_width / nrows
	row := int(y / gap)
	col := int(x / gap)
	match btn_type {
		.left {
			if app.start.x == -1 && !(row == app.end.y && col == app.end.x) {
				app.start.x = col
				app.start.y = row
				set_cell_type(mut app.grid, app.start.y, app.start.x, 'start')
			} else if app.end.x == -1 && !(row == app.start.y && col == app.start.x) {
				app.end.x = col
				app.end.y = row
				set_cell_type(mut app.grid, app.end.y, app.end.x, 'end')
			} else if !(row == app.start.y && col == app.start.x) && !(row == app.end.y
				&& col == app.end.x) {
				set_cell_type(mut app.grid, row, col, 'barrier')
			}
		}
		.right {
			if row == app.start.y && col == app.start.x {
				app.start.x = -1
				app.start.y = -1
			}
			if row == app.end.y && col == app.end.x {
				app.end.x = -1
				app.end.y = -1
			}

			set_cell_type(mut app.grid, row, col, 'reset')
		}
		else {}
	}
}

// handle keyboard interaction by user ''
fn (mut app App) on_key_down(key gg.KeyCode) {
	match key {
		.space {
			if app.start.x == -1 || app.end.x == -1 {
				println('Error: either start or end node is missing')
			} else {
				for row := 0; row < nrows; row++ {
					for j := 0; j < nrows; j++ {
						update_neighbors(mut app.grid, row, j)
					}
				}
				new_start := &Point{
					x: app.start.y
					y: app.start.x
				}
				new_end := &Point{
					x: app.end.y
					y: app.end.x
				}
				astar_path_finding(mut app, mut app.grid, new_start, new_end)
			}
		}
		.q {
			app.gg.quit()
		}
		.c {
			draw_grid(mut app)
			draw_gridlines(mut app)
			mut grid := initialise_grid()
			app.grid = grid // set grid to app attribute so you can access it by just passing app variable or with method of app
			app.ui.dpi_scale = 1.0 // set scale this is use to make it responsive
			app.start = &Point{ // set start point to -1, -1
				x: -1
				y: -1
			}
			app.end = &Point{ // set end point to -1, -1
				x: -1
				y: -1
			}
		}
		else {}
	}
}

// draw grid lines
fn draw_gridlines(mut app App) {
	dx := window_width / nrows
	dy := window_height / nrows
	for i := 0; i < nrows; i++ {
		// horizontal lines
		app.gg.draw_line(0, i * dy, window_width, i * dy, gg.black)
		// vertical lines
		app.gg.draw_line(i * dx, 0, dx * i, window_height, gg.black)
	}
}

// heuristic function(point manhatten distance) that calculate approximate cost to reach from a given point to end(target)
fn hf(p1 Point, p2 Point) int {
	return math.abs(p1.x - p2.x) + math.abs(p1.y - p2.y)
}

// initialize grid attribute of app
fn initialise_grid() [][]Cell {
	mut grid := [][]Cell{len: nrows, init: []Cell{len: nrows}}
	gap := window_width / nrows
	for i := 0; i < nrows; i++ {
		for j := 0; j < nrows; j++ {
			grid[i][j] = &Cell{
				row:   i
				col:   j
				width: gap
				pos:   &Point{
					x: j * gap
					y: i * gap
				}
				color: gg.white
				flag:  0
			}
		}
	}
	return grid
}

// draw the cells of grid
fn draw_grid(mut app App) {
	for i := 0; i < nrows; i++ {
		for j := 0; j < nrows; j++ {
			pos := app.grid[i][j].pos
			width := app.grid[i][j].width
			color := app.grid[i][j].color
			app.gg.draw_rect_filled(pos.x, pos.y, width, width, color)
		}
	}
}

// update the neighbor of each cell in which cell you can visit (if it is not barrier or end or start)
fn update_neighbors(mut grid [][]Cell, row int, col int) {
	if row < nrows - 1 && grid[row + 1][col].flag != 3 {
		grid[row][col].neighbors << &Point{
			x: row + 1
			y: col
		}
	}
	if row > 0 && grid[row - 1][col].flag != 3 {
		grid[row][col].neighbors << &Point{
			x: row - 1
			y: col
		}
	}
	if col < nrows - 1 && grid[row][col + 1].flag != 3 {
		grid[row][col].neighbors << &Point{
			x: row
			y: col + 1
		}
	}
	if col > 0 && grid[row][col - 1].flag != 3 {
		grid[row][col].neighbors << &Point{
			x: row
			y: col - 1
		}
	}
}

// construct the path after finding it shows as pink color
fn reconstruct_path(mut grid [][]Cell, mut came_from [][]Point, _start Point, end Point) {
	mut x := end.x
	mut y := end.y
	for !(x == -1 && y == -1) {
		set_cell_type(mut grid, x, y, 'path')
		x = came_from[x][y].x
		y = came_from[x][y].y
	}
}

// a* path finding algorithm
fn astar_path_finding(mut _app App, mut grid [][]Cell, start Point, end Point) {
	mut priority_queue := &MinHeap{}
	mut g_score := [][]int{len: nrows, init: []int{len: nrows}}
	mut f_score := [][]int{len: nrows, init: []int{len: nrows}}
	mut came_from := [][]Point{len: nrows, init: []Point{len: nrows}}
	for i := 0; i < nrows; i++ {
		for j := 0; j < nrows; j++ {
			g_score[i][j] = 1_000_000_000_00
			f_score[i][j] = 1_000_000_000_00
			came_from[i][j] = &Point{
				x: -1
				y: -1
			}
		}
	}

	g_score[start.x][start.y] = 0
	f_score[start.x][start.y] = g_score[start.x][start.y] + hf(start, end)
	priority_queue.insert(Node{
		f_score: f_score[start.x][start.y]
		cell:    &Point{
			x: start.x
			y: start.y
		}
		count:   0
	})

	for priority_queue.len() > 0 {
		curr_node := priority_queue.pop() or {
			panic('There is nothing in queue how did it reach here idk')
		}
		curr_pos := curr_node.cell
		set_cell_type(mut grid, curr_pos.x, curr_pos.y, 'close')

		if curr_pos.x == end.x && curr_pos.y == end.y {
			set_cell_type(mut grid, start.x, start.y, 'start')
			set_cell_type(mut grid, end.x, end.y, 'end')
			came_from[end.x][end.y] = came_from[curr_pos.x][curr_pos.y]
			reconstruct_path(mut grid, mut came_from, start, end)
			set_cell_type(mut grid, start.x, start.y, 'start')
			set_cell_type(mut grid, end.x, end.y, 'end')
			return
		}

		for neighbor in grid[curr_pos.x][curr_pos.y].neighbors {
			mut temp_g_score := g_score[curr_pos.x][curr_pos.y] + 1
			if temp_g_score < g_score[neighbor.x][neighbor.y] {
				g_score[neighbor.x][neighbor.y] = temp_g_score
				if !(neighbor.x == start.x && neighbor.y == start.y) {
					priority_queue.insert(Node{
						f_score: g_score[neighbor.x][neighbor.y] + hf(neighbor, end)
						cell:    neighbor
						count:   curr_node.count + 1
					})
					came_from[neighbor.x][neighbor.y] = curr_pos
					set_cell_type(mut grid, neighbor.x, neighbor.y, 'open')
				}
			}
		}
	}
	set_cell_type(mut grid, start.x, start.y, 'start')
}

// change the property of a cell
fn set_cell_type(mut grid [][]Cell, row int, col int, typ string) {
	match typ {
		'reset' {
			grid[row][col].color = gg.white
			grid[row][col].flag = 0
		}
		'close' {
			grid[row][col].color = gg.red
			grid[row][col].flag = 1
		}
		'open' {
			grid[row][col].color = gg.green
			grid[row][col].flag = 2
		}
		'barrier' {
			grid[row][col].color = gg.black
			grid[row][col].flag = 3
		}
		'start' {
			grid[row][col].color = gg.orange
			grid[row][col].flag = 4
		}
		'end' {
			grid[row][col].color = gg.blue
			grid[row][col].flag = 5
		}
		'path' {
			grid[row][col].color = gg.pink
			grid[row][col].flag = 6
		}
		else {}
	}
}

// ------------------------------ HEAP -----------------------------

fn (mut heap MinHeap) insert(item Node) {
	heap.data << item
}

// get the minimum out of all node
fn (mut heap MinHeap) pop() !Node {
	if heap.len() == 0 {
		return error('empty heap')
	}
	mut i := 0
	mut curr := heap.data[0].f_score
	len := heap.len()
	for idx := 0; idx < len; idx++ {
		if curr > heap.data[idx].f_score {
			i = idx
			curr = heap.data[idx].f_score
		}
	}
	ele := heap.data[i]
	heap.data.delete(i)
	return ele
}

// see the top element of heap //TODO this won't give correct result as heap is not implemented correctly
fn (mut heap MinHeap) peek() !Node {
	if heap.data.len == 0 {
		return error('Heap is empty')
	}
	return heap.data[0]
}

// give length of heap total element present currently
fn (mut heap MinHeap) len() int {
	return heap.data.len
}

// Index of left child of a node in heap //TODO heap not implemented
fn (mut heap MinHeap) left_child(idx int) !int {
	child := 2 * idx + 1
	if child >= heap.data.len {
		return error('Out of Bound')
	}
	return child
}

// Index of right child of a node in heap //TODO heap not implemented
fn (mut heap MinHeap) right_child(idx int) !int {
	child := 2 * idx + 2
	if child >= heap.data.len {
		return error('Out of bound')
	}
	return child
}

// Index of parent of a node in heap //TODO heap not implemented
fn (mut heap MinHeap) parent(idx int) int {
	return (idx - 1) / 2
}

// vtest build: !openbsd
module main

import gg
import rand
import sokol.audio
import math

const paddle_speed_base = f32(400.0)
const ball_speed_base = f32(300.0)

// Colors
const color_bg = gg.Color{10, 15, 30, 255}
const color_foreground = gg.Color{230, 230, 230, 255}
const color_accent = gg.Color{0, 255, 100, 255}
const color_secondary = gg.Color{0, 200, 80, 255}
const color_text_dim = gg.Color{150, 150, 150, 200}
const color_line = gg.Color{100, 100, 100, 150}
const color_p1 = gg.Color{255, 50, 50, 255}
const color_p2 = gg.Color{50, 100, 255, 255}

struct SoundManager {
mut:
	ping []f32
	pong []f32
	buzz []f32
}

fn (mut sm SoundManager) init() {
	sample_rate := f32(audio.sample_rate())

	// Ping (Wall)
	ping_duration := f32(0.1)
	ping_frames := int(sample_rate * ping_duration)
	for i in 0 .. ping_frames {
		t := f32(i) / sample_rate
		// Use a steeper exponential-like decay for a cleaner "pluck"
		env := f32(math.pow(f32(1.0) - t / ping_duration, 3))
		sm.ping << f32(0.3) * math.sinf(t * 800.0 * 2 * math.pi) * env
	}
	// Absolute silence buffer to prevent clicks
	for _ in 0 .. 100 {
		sm.ping << 0
	}

	// Pong (Paddle)
	pong_duration := f32(0.1)
	pong_frames := int(sample_rate * pong_duration)
	for i in 0 .. pong_frames {
		t := f32(i) / sample_rate
		env := f32(math.pow(f32(1.0) - t / pong_duration, 3))
		sm.pong << f32(0.3) * math.sinf(t * 400.0 * 2 * math.pi) * env
	}
	for _ in 0 .. 100 {
		sm.pong << 0
	}

	// Buzz (Reset)
	buzz_duration := f32(0.3)
	buzz_frames := int(sample_rate * buzz_duration)
	for i in 0 .. buzz_frames {
		t := f32(i) / sample_rate
		env := f32(math.pow(f32(1.0) - t / buzz_duration, 2))
		// Add a harmonic for a more "buzzy" feel
		val := f32(0.25) * math.sinf(t * 100.0 * 2 * math.pi) +
			f32(0.1) * math.sinf(t * 200.0 * 2 * math.pi)
		sm.buzz << val * env
	}
	for _ in 0 .. 200 {
		sm.buzz << 0
	}
}

struct App {
mut:
	ctx           &gg.Context = unsafe { nil }
	width         int         = 800
	height        int         = 600
	paddle_width  f32
	paddle_height f32
	ball_size     f32
	p1_y          f32
	p2_y          f32
	ball_x        f32
	ball_y        f32
	ball_vx       f32
	ball_vy       f32
	p1_score      int
	p2_score      int
	paused        bool
	sounds        SoundManager
}

fn (mut app App) update_sizes() {
	size := app.ctx.window_size()
	app.width = size.width
	app.height = size.height

	// Base scales on 800x600
	scale_x := f32(app.width) / 800.0
	scale_y := f32(app.height) / 600.0

	app.paddle_width = 15.0 * scale_x
	app.paddle_height = 80.0 * scale_y
	app.ball_size = 15.0 * scale_x // Keep it circular based on width scale
}

fn (mut app App) reset_ball() {
	app.ball_x = f32(app.width) / 2 - app.ball_size / 2
	app.ball_y = f32(app.height) / 2 - app.ball_size / 2

	scale_x := f32(app.width) / 800.0
	mut vx := ball_speed_base * scale_x
	if rand.intn(2) or { 0 } == 0 {
		vx = -vx
	}
	app.ball_vx = vx
	app.ball_vy = (f32(rand.intn(301) or { 150 } - 150)) * (f32(app.height) / 600.0)
}

fn (mut app App) reset_game() {
	app.p1_score = 0
	app.p2_score = 0
	app.p1_y = f32(app.height) / 2 - app.paddle_height / 2
	app.p2_y = f32(app.height) / 2 - app.paddle_height / 2
	app.reset_ball()
	app.paused = false
}

fn on_frame(data voidptr) {
	mut app := unsafe { &App(data) }
	app.ctx.begin()

	// Draw dashed center line
	line_segments := 20
	segment_height := f32(app.height) / line_segments
	for i in 0 .. line_segments {
		if i % 2 == 0 {
			app.ctx.draw_rect_filled(f32(app.width) / 2 - 1, i * segment_height, 2, segment_height,
				color_line)
		}
	}

	// Draw paddles
	app.ctx.draw_rounded_rect_filled(20, app.p1_y, app.paddle_width, app.paddle_height, 5, color_p1)
	app.ctx.draw_rounded_rect_filled(f32(app.width) - 20 - app.paddle_width, app.p2_y,
		app.paddle_width, app.paddle_height, 5, color_p2)

	// Draw ball
	app.ctx.draw_circle_filled(app.ball_x + app.ball_size / 2, app.ball_y + app.ball_size / 2,
		app.ball_size / 2, color_foreground)

	// Draw ball speed (10m = 800px => 1m = 80px)
	// We scale the meter definition with width
	meter_px := 80.0 * (f32(app.width) / 800.0)
	speed_px := math.sqrt(app.ball_vx * app.ball_vx + app.ball_vy * app.ball_vy)
	speed_ms := speed_px / meter_px
	app.ctx.draw_text(app.width / 2, 20, 'Ball: ${speed_ms:.1f} m/s',
		size:  20
		color: color_foreground
		align: .center
	)

	// Draw scores and positions
	// Moved up to be less obtrusive
	app.ctx.draw_text(app.width / 4, 30, app.p1_score.str(),
		size:  40
		color: color_accent
		align: .center
	)
	app.ctx.draw_text(app.width / 4, 80, 'Y: ${int(app.p1_y)}',
		size:  16
		color: color_secondary
		align: .center
	)

	app.ctx.draw_text(3 * app.width / 4, 30, app.p2_score.str(),
		size:  40
		color: color_accent
		align: .center
	)
	app.ctx.draw_text(3 * app.width / 4, 80, 'Y: ${int(app.p2_y)}',
		size:  16
		color: color_secondary
		align: .center
	)

	if app.paused {
		app.ctx.draw_text(app.width / 2, app.height / 2 - 50, 'PAUSED',
			size:  64
			color: color_accent
			align: .center
		)
		app.ctx.draw_text(app.width / 2, app.height / 2 + 10, 'Press SPACE to Resume',
			size:  20
			color: color_accent
			align: .center
		)
	} else {
		app.ctx.draw_text(app.width / 2, app.height - 25,
			'SPACE: Pause | W/S: P1 | UP/DOWN: P2 | R: Reset',
			size:  16
			color: color_text_dim
			align: .center
		)
	}

	app.ctx.end()
}

fn on_event(e &gg.Event, data voidptr) {
	mut app := unsafe { &App(data) }
	if e.typ == .resized || e.typ == .restored {
		app.update_sizes()
	}
	if e.typ == .key_down {
		match e.key_code {
			.space { app.paused = !app.paused }
			.r { app.reset_game() }
			else {}
		}
	}
}

fn on_update(dt f32, data voidptr) {
	mut app := unsafe { &App(data) }

	if app.paused {
		return
	}

	scale_y := f32(app.height) / 600.0
	paddle_speed := paddle_speed_base * scale_y

	// Paddle 1 movement (W/S)
	if app.ctx.pressed_keys[gg.KeyCode.w] {
		app.p1_y -= paddle_speed * dt
	}
	if app.ctx.pressed_keys[gg.KeyCode.s] {
		app.p1_y += paddle_speed * dt
	}

	// Paddle 2 movement (Up/Down)
	if app.ctx.pressed_keys[gg.KeyCode.up] {
		app.p2_y -= paddle_speed * dt
	}
	if app.ctx.pressed_keys[gg.KeyCode.down] {
		app.p2_y += paddle_speed * dt
	}

	// Constrain paddles
	if app.p1_y < 0 {
		app.p1_y = 0
	}
	if app.p1_y > f32(app.height) - app.paddle_height {
		app.p1_y = f32(app.height) - app.paddle_height
	}
	if app.p2_y < 0 {
		app.p2_y = 0
	}
	if app.p2_y > f32(app.height) - app.paddle_height {
		app.p2_y = f32(app.height) - app.paddle_height
	}

	// Ball movement
	app.ball_x += app.ball_vx * dt
	app.ball_y += app.ball_vy * dt

	// Ball wall collision (Top/Bottom)
	if app.ball_y <= 0 {
		app.ball_y = 0
		app.ball_vy = -app.ball_vy
		audio.push(app.sounds.ping.data, app.sounds.ping.len)
	} else if app.ball_y >= f32(app.height) - app.ball_size {
		app.ball_y = f32(app.height) - app.ball_size
		app.ball_vy = -app.ball_vy
		audio.push(app.sounds.ping.data, app.sounds.ping.len)
	}

	// Ball paddle collision
	// P1
	if app.ball_vx < 0 && app.ball_x <= 20 + app.paddle_width && app.ball_x >= 20 {
		if app.ball_y + app.ball_size >= app.p1_y && app.ball_y <= app.p1_y + app.paddle_height {
			app.ball_x = 20 + app.paddle_width
			app.ball_vx = -app.ball_vx * 1.05 // Slightly speed up
			// Add some vertical velocity based on where it hit the paddle
			hit_pos := (app.ball_y + app.ball_size / 2) - (app.p1_y + app.paddle_height / 2)
			app.ball_vy += hit_pos * 5
			audio.push(app.sounds.pong.data, app.sounds.pong.len)
		}
	}

	// P2
	if app.ball_vx > 0 && app.ball_x + app.ball_size >= f32(app.width) - 20 - app.paddle_width
		&& app.ball_x + app.ball_size <= f32(app.width) - 20 {
		if app.ball_y + app.ball_size >= app.p2_y && app.ball_y <= app.p2_y + app.paddle_height {
			app.ball_x = f32(app.width) - 20 - app.paddle_width - app.ball_size
			app.ball_vx = -app.ball_vx * 1.05 // Slightly speed up
			// Add some vertical velocity based on where it hit the paddle
			hit_pos := (app.ball_y + app.ball_size / 2) - (app.p2_y + app.paddle_height / 2)
			app.ball_vy += hit_pos * 5
			audio.push(app.sounds.pong.data, app.sounds.pong.len)
		}
	}

	// Score
	if app.ball_x < 0 {
		app.p2_score++
		app.reset_ball()
		audio.push(app.sounds.buzz.data, app.sounds.buzz.len)
	} else if app.ball_x > f32(app.width) {
		app.p1_score++
		app.reset_ball()
		audio.push(app.sounds.buzz.data, app.sounds.buzz.len)
	}
}

fn main() {
	mut app := &App{}
	app.width = 800
	app.height = 600
	app.paddle_width = 15.0
	app.paddle_height = 80.0
	app.ball_size = 15.0
	app.p1_y = f32(app.height) / 2 - app.paddle_height / 2
	app.p2_y = f32(app.height) / 2 - app.paddle_height / 2
	app.reset_ball()

	audio.setup(buffer_frames: 512)
	app.sounds.init()

	app.ctx = gg.new_context(
		width:         app.width
		height:        app.height
		window_title:  'V Pong'
		user_data:     app
		frame_fn:      on_frame
		event_fn:      on_event
		update_fn:     on_update
		bg_color:      color_bg
		resizable:     true
		create_window: true
	)

	app.ctx.run()
}

