import gg
import gg.m4
import math
import sokol.gfx
// import sokol.sgl
import time

const win_width = 800
const win_height = 800
const bg_color = gg.white
const num_inst = 16384

struct App {
mut:
	gg          &gg.Context = unsafe { nil }
	texture     gfx.Image
	sampler     gfx.Sampler
	init_flag   bool
	frame_count int

	mouse_x    int = 903
	mouse_y    int = 638
	mouse_down bool
	// glsl
