			gfx.draw_text(x, y + 2, '█████')
			gfx.draw_text(x, y + 3, '    █')
			gfx.draw_text(x, y + 4, '█████')
		}
		else {}
	}
}

fn (mut g Game) draw() {
	mut gfx := g.app.tui
	gfx.set_bg_color(white)
	// Border
	gfx.draw_empty_rect(1, 1, g.app.width, g.app.height)
	// Center line
	gfx.draw_dashed_line(int(f32(g.app.width) * 0.5), 0, int(f32(g.app.width) * 0.5),
		int(g.app.height))
	border := 1
	mut y, mut x := 0, 0
	for p in g.players {
		x = int(p.pos.x)
		y = int(p.pos.y)
		gfx.reset_bg_color()
		gfx.set_color(white)
		if x < f32(g.app.width) * 0.5 {
			g.draw_big_digit(f32(g.app.width) * 0.25, 3, p.score)
		} else {
			g.draw_big_digit(f32(g.app.width) * 0.75, 3, p.score)
		}
		gfx.reset_color()
		gfx.set_bg_color(white)
		// Racket
		gfx.draw_line(x, y + border, x, y + p.racket_size)
	}
	// Ball
	gfx.draw_point(int(g.ball.pos.x), int(g.ball.pos.y))
	// gfx.draw_text(22,2,'${g.ball.pos}')
	gfx.reset_bg_color()
}

fn (mut g Game) free() {
	g.players.clear()
}

// TODO: Remove these wrapper functions when we can assign methods as callbacks
fn init(mut app App) {
	app.init()
}

fn frame(mut app App) {
	app.frame()
}

fn cleanup(mut app App) {
	unsafe {
		app.free()
	}
}

fn fail(error string) {
	eprintln(error)
}

fn event(e &ui.Event, mut app App) {
	app.event(e)
}

type InitFn = fn (voidptr)

type EventFn = fn (&ui.Event, voidptr)

type FrameFn = fn (voidptr)

type CleanupFn = fn (voidptr)

fn main() {
	mut app := &App{}
	app.tui = ui.init(
		user_data:      app
		// The tui callback slots are `voidptr`; these handlers (`init`, `frame`, `cleanup`,
		// `event`) instead take the typed app pointer that `user_data` hands back. `&T` and
		// `voidptr` share a representation, so reinterpreting each fn pointer across that
		// parameter is ABI-safe; the casts only satisfy the static fn-type check.
		init_fn:        unsafe { InitFn(init) }
		frame_fn:       unsafe { FrameFn(frame) }
		cleanup_fn:     unsafe { CleanupFn(cleanup) }
		event_fn:       unsafe { EventFn(event) }
		fail_fn:        fail
		capture_events: true
		hide_cursor:    true
		frame_rate:     60
	)
	app.tui.run()!
}

import term.ui as tui
import rand

struct Rect {
mut:
	c  tui.Color
	x  int
	y  int
	x2 int
	y2 int
}

struct App {
mut:
	tui      &tui.Context = unsafe { nil }
	rects    []Rect
	cur_rect Rect
	is_drag  bool
	redraw   bool
}

fn random_color() tui.Color {
	return tui.Color{
		r: rand.u8()
		g: rand.u8()
		b: rand.u8()
	}
}

fn event(e &tui.Event, mut app App) {
	match e.typ {
		.mouse_down {
			app.is_drag = true
			app.cur_rect = Rect{
				c:  random_color()
				x:  e.x
				y:  e.y
				x2: e.x
				y2: e.y
			}
		}
		.mouse_drag {
			app.cur_rect.x2 = e.x
			app.cur_rect.y2 = e.y
		}
		.mouse_up {
			app.rects << app.cur_rect
			app.is_drag = false
		}
		.key_down {
			if e.code == .c {
				app.rects.clear()
			} else if e.code == .escape {
				exit(0)
			}
		}
		else {}
	}

	app.redraw = true
}

fn frame(mut app App) {
	if !app.redraw {
		return
	}

	app.tui.clear()

	for rect in app.rects {
		app.tui.set_bg_color(rect.c)
		app.tui.draw_rect(rect.x, rect.y, rect.x2, rect.y2)
	}

	if app.is_drag {
		r := app.cur_rect
		app.tui.set_bg_color(r.c)
		app.tui.draw_empty_rect(r.x, r.y, r.x2, r.y2)
	}

	app.tui.reset_bg_color()
	app.tui.flush()
	app.redraw = false
}

type EventFn = fn (&tui.Event, voidptr)

type FrameFn = fn (voidptr)

fn main() {
	mut app := &App{}
	app.tui = tui.init(
		user_data:   app
		// The tui callback slots are `voidptr`; `frame`/`event` instead take the typed app
		// pointer that `user_data` hands back. `&T` and `voidptr` share a representation, so
		// reinterpreting the fn pointer across that parameter is ABI-safe; the cast only
		// satisfies the static fn-type check.
		event_fn:    unsafe { EventFn(event) }
		frame_fn:    unsafe { FrameFn(frame) }
		hide_cursor: true
		frame_rate:  60
	)
	app.tui.run()!
}

