fn describe_message(msg websocket.Message) !string {
	return match msg.opcode {
		.text_frame {
			'text:${msg.payload.bytestr()}'
		}
		.ping {
			'ping'
		}
		else {
			error('unsupported websocket message opcode')
		}
	}
}

