import context
import time
import x.async as xasync

fn main() {
	mut pool := xasync.new_pool(workers: 1, queue_size: 1)!
	started := chan int{cap: 2}
	release := chan bool{cap: 2}
	job := fn [started, release] (mut ctx context.Context) ! {
		_ = ctx
		started <- 1
		_ := <-release
	}

	pool.try_submit(job)!
	if !wait_started(started) {
		eprintln('pool job did not start')
		exit(1)
	}

	pool.try_submit(job)!
	pool.try_submit(job) or { println('backpressure: ${err.msg()}') }

	release <- true
	if !wait_started(started) {
		eprintln('pool job did not start')
		exit(1)
	}
	release <- true

	pool.close()!
	println('pool drained')
}

fn wait_started(started chan int) bool {
	select {
		_ := <-started {
			return true
		}
		1 * time.second {
			return false
		}
	}
	return false
}

# net.http integration tests

These tests use `net.http` request and response values in memory. They do not
open a listener, bind a port, or call an external service.

The coverage target is the `x.async` boundary around HTTP-shaped work:

- bounded pool submission;
- explicit queue-full backpressure;
- draining accepted request handlers through `Pool.close()`;
- preserving response data produced by accepted jobs.

module main

import x.atomics

fn main() {
	// Basic atomic load and store operations
	mut value := i32(0)

	// Atomically store a value
	atomics.store_i32(&value, 42)

	// Atomically load the value
	loaded := atomics.load_i32(&value)
	println('Loaded value: ${loaded}') // Output: 42

	// Atomic add: returns the new value after addition
	new_value := atomics.add_i32(&value, 10)
	println('After add: ${new_value}') // Output: 52

	// Atomic swap: returns the old value
	old := atomics.swap_i32(&value, 100)
	println('Old value: ${old}, new value: ${atomics.load_i32(&value)}') // Output: 52, 100
}

module main

import x.atomics

struct SpinLock {
mut:
	state u32 // 0 = unlocked, 1 = locked
}

fn acquire(mut spinlock SpinLock) {
	for !atomics.cas_u32(&spinlock.state, 0, 1) {
		// Busy-wait
	}
}

fn release(mut spinlock SpinLock) {
	atomics.store_u32(&spinlock.state, 0)
}

struct SharedData {
mut:
	spinlock SpinLock
	value    int
}

fn worker(mut data SharedData, iterations int) {
	for _ in 0 .. iterations {
		acquire(mut data.spinlock)
		data.value++
		release(mut data.spinlock)
	}
}

fn main() {
	mut data := &SharedData{}

	num_threads := 4
	iterations_per_thread := 10000

	mut threads := []thread{}

	for _ in 0 .. num_threads {
		threads << spawn worker(mut data, iterations_per_thread)
	}

	threads.wait()

	expected := num_threads * iterations_per_thread
	actual := data.value

	println('Expected: ${expected}')
	println('Actual:   ${actual}')

	if actual == expected {
		println('Spinlock works correctly')
	} else {
		println('Race condition detected')
	}
}

