import x.encoding.asn1

// This example of encode a sequence containing a UTF-8 string, an integer
// and an explicitly tagged object identifier, conforming to the following
// ASN.1 schema specification:

// ```asn.1
// Example ::= SEQUENCE {
//    greeting    UTF8String,
//    answer      INTEGER,
//    type        [1] EXPLICIT OBJECT IDENTIFIER
// }
// ```

// You can represent above structure with related structure in `v`, similar like:

struct Example {
	greeting asn1.Utf8String
	answer   asn1.Integer
	// you can tag your struct fields with supported options.
	tipe asn1.ObjectIdentifier @[context_specific: 1; explicit; inner: 6]
}

fn (ex Example) tag() asn1.Tag {
	return asn1.default_sequence_tag
}

// you can build your payload manually or use `asn1.make_payload`, but with aware,
// if your structure contains generic, its maybe not work (currently).
fn (ex Example) payload() ![]u8 {
	kd := asn1.KeyDefault(map[string]asn1.Element{})
	payload := asn1.make_payload[Example](ex, kd)!
	return payload
}

// You can write routines for deserialize Example structure. This is only examples way,
// but its possible to use other way with the help from this module, like use
// `Parser` codec.
fn Example.decode(bytes []u8) !Example {
	// just call raw .decode on bytes
	// by example, its should produce sequence type.
	elem := asn1.decode(bytes)!
	assert elem.tag().equal(asn1.default_sequence_tag) // should true

	// cast produced element into Sequence type and get the fields.
	seq := elem.into_object[asn1.Sequence]()!
	fields := seq.fields()

	// and then, turn every field into desired object based your schema.
	// first two field is not wrapped element, so just turn into real object
	greeting := fields[0].into_object[asn1.Utf8String]()!
	answer := fields[1].into_object[asn1.Integer]()!

	// the third field is context_specific wrapped element, just unwrap it with the
	// same options used to encode
	oid_tipe := fields[2].unwrap_with_options('context_specific:1;explicit; inner:6')!
	tipe := oid_tipe.into_object[asn1.ObjectIdentifier]()!

	// then build your Example structure
	ex := Example{
		greeting: greeting
		answer:   answer
		tipe:     tipe
	}
	return ex
}

fn main() {
	expected_output := [u8(0x30), 18, u8(12), 5, 72, 101, 108, 108, 111, u8(2), 1, 42, u8(0xA1),
		6, 6, 4, 43, 6, 1, 3]
	ex := Example{
		greeting: asn1.Utf8String.new('Hello')!
		answer:   asn1.Integer.from_int(42)
		tipe:     asn1.ObjectIdentifier.new('1.3.6.1.3')!
	}

	// serialize the Example object
	out := asn1.encode(ex)!
	assert out == expected_output

	// test with data
	example_obj := Example.decode(out)!
	dump(ex.greeting == example_obj.greeting)
	dump(ex.answer == example_obj.answer)
	dump(ex.tipe == example_obj.tipe)
}

import x.executor

fn main() {
	mut ex := executor.new(queue_size: 4)!
	updates := chan string{cap: 1}

	ex.try_post(fn [updates] () ! {
		updates <- 'owner state updated'
	})!

	ran := ex.run_one()!
	if !ran {
		eprintln('executor did not run the queued job')
		exit(1)
	}

	println(<-updates)
	ex.stop()
	if ex.run_one()! {
		eprintln('unexpected job after stop')
		exit(1)
	}
	ex.wait()!
}

import time
import x.executor

fn main() {
	mut ex := executor.new(queue_size: 1)!
	ran := chan string{cap: 2}

	ex.try_post(fn [ran] () ! {
		ran <- 'first'
	})!

	ex.try_post(fn () ! {}) or { println('try_post backpressure: ${err.msg()}') }

	ex.post_with_timeout(20 * time.millisecond, fn () ! {}) or {
		println('timeout bounded admission: ${err.msg()}')
	}

	if !ex.run_one()! {
		eprintln('queued job did not run')
		exit(1)
	}
	println(<-ran)

	ex.stop()
	if ex.run_one()! {
		eprintln('unexpected job after stop')
		exit(1)
	}
	ex.wait()!
}

import x.executor

fn main() {
	mut ex := executor.new(queue_size: 8)!
	events := chan int{cap: 6}

	for i in 0 .. 6 {
		ex.try_post(fn [events, i] () ! {
			events <- i
		})!
	}

	mut frame := 0
	mut drained_total := 0
	for drained_total < 6 {
		frame++
		drained := ex.drain_pending(2)!
		if drained == 0 {
			eprintln('frame ${frame} did not drain any work')
			exit(1)
		}
		drained_total += drained
		println('frame ${frame}: drained ${drained} owner jobs')
	}

	mut checksum := 0
	for _ in 0 .. 6 {
		checksum += <-events
	}
	println('checksum=${checksum}')

	ex.stop()
	if ex.drain_pending(1)! != 0 {
		eprintln('unexpected job after stop')
		exit(1)
	}
	ex.wait()!
}

import x.executor

fn main() {
	mut ex := executor.new(queue_size: 4)!
	result := chan string{cap: 1}
	run_result := chan string{cap: 1}

	runner := spawn fn [mut ex, run_result] () {
		ex.run() or {
			run_result <- err.msg()
			return
		}
		run_result <- 'ok'
	}()

	caller := spawn fn [mut ex, result] () {
		ex.run_sync(fn [result] () ! {
			result <- 'ran on owner loop'
		}) or { result <- 'run_sync failed: ${err.msg()}' }
	}()

	msg := <-result
	if msg != 'ran on owner loop' {
		eprintln(msg)
		exit(1)
	}
	println(msg)

	ex.stop()
	run_msg := <-run_result
	if run_msg != 'ok' {
		eprintln('run failed: ${run_msg}')
		exit(1)
	}
	ex.wait()!
	caller.wait()
	runner.wait()
}

import x.executor

fn main() {
	mut ex := executor.new(queue_size: 2)!
	ran := chan bool{cap: 1}
	run_result := chan string{cap: 1}

	ex.try_post(fn [mut ex, ran] () ! {
		ex.stop()
		ran <- true
	})!

	runner := spawn fn [mut ex, run_result] () {
		ex.run() or {
			run_result <- err.msg()
			return
		}
		run_result <- 'ok'
	}()

	did_run := <-ran
	if !did_run {
		eprintln('owner stop job did not run')
		exit(1)
	}
	msg := <-run_result
	if msg != 'ok' {
		eprintln('run returned error: ${msg}')
		exit(1)
	}

	ex.try_post(fn () ! {}) or { println('submit after stop: ${err.msg()}') }
	ex.wait()!
	runner.wait()
}

import x.executor

struct FakeHandle {
mut:
	calls int
}

fn main() {
	mut owner := executor.new(queue_size: 4)!
	result := chan int{cap: 1}
	mut handle := FakeHandle{}

	owner.try_post(fn [mut handle, result] () ! {
		handle.calls++
		handle.calls++
		result <- handle.calls
	})!

	if !owner.run_one()! {
		eprintln('owner job did not run')
		exit(1)
	}
	calls := <-result
	if calls != 2 {
		eprintln('unexpected handle call count: ${calls}')
		exit(1)
	}

	println('synthetic FFI handle calls=${calls}')
	owner.stop()
	if owner.run_one()! {
		eprintln('unexpected owner job after stop')
		exit(1)
	}
	owner.wait()!
}

import x.executor

struct TextureUpload {
	id    int
	bytes int
}

fn main() {
	mut render := executor.new(queue_size: 8)!
	uploaded := chan TextureUpload{cap: 3}
	producer_done := chan bool{cap: 1}

	producer := spawn fn [mut render, producer_done, uploaded] () {
		for id in 0 .. 3 {
			bytes := 128 + id
			render.try_post(fn [uploaded, id, bytes] () ! {
				uploaded <- TextureUpload{
					id:    id
					bytes: bytes
				}
			}) or {
				producer_done <- false
				return
			}
		}
		producer_done <- true
	}()

	producer_ok := <-producer_done
	if !producer_ok {
		eprintln('producer could not submit render uploads')
		exit(1)
	}
	drained := render.drain_pending(8)!
	if drained != 3 {
		eprintln('expected 3 render uploads, got ${drained}')
		exit(1)
	}

	mut total_bytes := 0
	for _ in 0 .. 3 {
		total_bytes += (<-uploaded).bytes
	}
	println('uploaded ${drained} synthetic textures, bytes=${total_bytes}')

	render.stop()
	if render.drain_pending(1)! != 0 {
		eprintln('unexpected render job after stop')
		exit(1)
	}
	render.wait()!
	producer.wait()
}

# Sessions

A sessions module for web projects.

## Usage

The sessions module provides an implementation for [session stores](#custom-stores).
The session store handles the saving, storing and retrieving of data. You can
either use a store directly yourself, or you can use the `session.Sessions` struct
which is easier to use since it also handles session verification and integrates nicely
with veb.

If you want to use `session.Sessions` in your web app the session id's will be
stored using cookies. The best way to get started is to follow the
[getting started](#getting-started) section.

Otherwise have a look at the [advanced usage](#advanced-usage) section.

## Getting Started

The examples in this section use `x.veb`. See the [advanced usage](#advanced-usage) section
for examples without `x.veb`.

To start using sessions in veb embed `sessions.CurrentSession` on the
Context struct and add `sessions.Sessions` to the app struct. We must also pass the type
of our session data.

For any further example code we will use the `User` struct.
**Example:**

```v ignore
import x.sessions
import veb

pub struct User {
pub mut:
	name	 string
	verified bool
}

pub struct Context {
	veb.Context
	// By embedding the CurrentSession struct we can directly access the current session id
	// and any associated session data. Set the session data type to `User`
	sessions.CurrentSession[User]
}

pub struct App {
pub mut:
	// this struct contains the store that holds all session data it also provides
	// an easy way to manage sessions in your veb app. Set the session data type to `User`
	sessions &sessions.Sessions[User]
}
```

Next we need to create the `&sessions.Sessions[User]` instance for our app. This
struct provides functionality to easier manage sessions in a veb app.

### Session Stores

To create `sessions.Sessions` We must specify a "store" which handles the session data.
Currently veb provides two options for storing session data:

1. The `MemoryStore[T]` stores session data in memory only using the `map` datatype.
2. The `DBStore[T]` stores session data in a database by encoding the session data to JSON.
   It will create the table `DBStoreSessions` in your database, to store the session data.

It is possible to create your own session store, see [custom stores](#custom-stores).

### Starting the App

For this example we will use the memory store.

**Example:**

```v ignore
fn main() {
	mut app := &App{
		sessions: &sessions.Sessions[User]{
			store: sessions.MemoryStore[User]{}
			// use your own secret which will be used to verify session id's
			secret: 'my secret'.bytes()
		}
	}

	veb.run[App, Context](mut app, 8080)
}
```

### Middleware

The `sessions.veb_middleware` module provides a middleware handler. This handler will execute
before your own route handlers and will verify the current session and fetch any associated
session data and load it into `sessions.CurrentSession`, which is embedded on the Context struct.

> **Note:**
> It is recommended to use the middleware, so the sessions are always verified
> and loaded correctly.

**Example:**

```v ignore
// add this import at the top of your file
import x.sessions.veb_middleware

pub struct App {
    // embed the Middleware struct from veb
    veb.Middleware[Context]
pub mut:
	// this struct contains the store that holds all session data it also provides
	// an easy way to manage sessions in your veb app. Set the session data type to `User`
	sessions &sessions.Sessions[User]
}

fn main() {
	mut app := &App{
		sessions: &sessions.Sessions[User]{
			store: sessions.MemoryStore[User]{}
			// use your own secret which will be used to verify session id's
			secret: 'my secret'.bytes()
		}
	}

    // register the sessions middleware
    app.use(veb_middleware.create[User, Context](mut app.sessions))

	veb.run[App, Context](mut app, 8080)
}
```

You can now start using sessions with veb!

### Usage in endpoint handlers

#### Using Session Data

Because `sessions.CurrentSession` is embedded on the Context struct we can directly
access any session data via `ctx.session_data`. This field is an option, it will be `none`
if no data is set.

**Example:**

```v ignore
pub fn (app &App) index(mut ctx Context) veb.Result {
	// check if a user is logged in
	if user := ctx.session_data {
		return ctx.text('Welcome ${user.name}! Verification status: ${user.verified}')
	} else {
		// user is not logged in
		return ctx.text('You are not logged in :(')
	}
}
```

#### Saving / updating session data

You can use the `save` method to update and save any session data.

When the user logs in, the `save` method is called and a new session id is generated
and set as cookie. Assuming there wasn't already a session going on. If you want to
be sure that a new session id is generated when you save data, you can use the `resave`
method. This method will save the data and *always* set a new session id.

**Example:**

```v ignore
pub fn (mut app App) login(mut ctx Context) veb.Result {
	// set a session id cookie and save data for the new user
	app.sessions.save(mut ctx, User{
		name: '[no name provided]'
	}) or { return ctx.server_error('could not save session data, please try again') }
	return ctx.text('You are now logged in!')
}
```

The following endpoint checks if a session exists, if it doesn't inform the
user that they need to login.

If a session does exists the users name is updated to the `name` query parameter,
you can use this route via `http://localhost:8080/save?name=myname`. And if the
query parameter is not passed an error 400 (bad request) is returned.

**Example:**

```v ignore
pub fn (mut app App) save(mut ctx Context) veb.Result {
	// check if there is a session
	app.sessions.get(ctx) or { return ctx.request_error('You are not logged in :(') }

	if name := ctx.query['name'] {
		// update the current user
		app.sessions.save(mut ctx, User{
			name: name
		}) or { return ctx.server_error('could not save session data, please try again') }
		return ctx.redirect('/', typ: .see_other)
	} else {
		// send HTTP 400 error
		return ctx.request_error('query parameter "name" must be present!')
	}
}
```

#### Destroying data / logging out

If a user logs out you can use the `logout` method to destroy the session data and
clear the session id cookie. If you only want to destroy the session data use the `destroy`
method.

**Example:**

```v ignore
pub fn (mut app App) logout(mut ctx Context) veb.Result {
	app.sessions.logout(mut ctx) or { return ctx.server_error('could not logout, please try again') }
	return ctx.text('You are now logged out!')
}
```

### Configuration

Change the `cookie_options` field to modify how the session cookie is stored.

**Example:**

```v ignore
mut app := &App{
	sessions: &sessions.Sessions[User]{
		// ...
		cookie_options: sessions.CookieOptions{
			// cookie can only be stored on an HTTPS site.
			secure: true
		}
	}
}
```

#### Mag-age

By default the expiration date of a session is 30 days. You can change this by
setting the `max_age` field. If `max_age = 0`, then session expiration times are not
checked and sessions will be stored forever until they are destroyed.

#### Pre-sessions

By default a session cookie is only generated when you call `save`, or `resave`.
By setting `save_uninitialized` to `true` a session cookie will always be set,
even if there is no data for the session yet. This is useful when you need session
data to be always available.

Or, for example, you could use pre-sessions to mitigate login-csrf,
since you can bind a csrf-token to the "pre-session" id. Then when the user logs
in, you can set a new session id with `resave`..

## Advanced Usage

If you want to store session id's in another manner than cookies, or if you want
to use this sessions module outside of veb, the easiest way is to create an
instance of a `Store` and directly interact with it.

First we create an instance of the `MemoryStore` and pass the user struct as data type.
**Example:**

```v
import x.sessions

const secret = 'my secret'.bytes()

pub struct User {
pub mut:
	name     string
	verified bool
}

fn main() {
	mut store := sessions.MemoryStore[User]{}

	user := User{
		name: 'vaesel'
	}
}
```

### Generating and validating session id's

The session module provides a function for generating a new signed session id
and for verifying a signed session id. You can ofcourse generate your own session id's.

**Example:**

```v ignore
// fn main
// generate a new session id and sign it
session_id, signed_session_id := sessions.new_session_id(secret)
// save session data to our store
store.set(session_id, user)!

// get a normal session id from the signed version and verify it
verified_session_id, valid := sessions.verify_session_id(signed_session_id, secret)
assert verified_session_id == session_id && valid == true
```

We can retrieve the saved user and verify that the data we saved can be retrieved
from the verified session id.

**Example:**

```v ignore
// fn main
// pass `max_age = 0` to ignore the expiration time.
if saved_user := store.get(verified_session_id, 0) {
	assert user == saved_user
	println('Retrieved a valid user! ${saved_user}')
} else {
	println(':(')
}
```

## Custom Stores

You can easily create your own custom store in order to control how session data is
stored and retrieved. Each session store needs to implement the `Store[T]` interface.

```v ignore
pub interface Store[T] {
mut:
	// get the current session data if the id exists and if it's not expired.
	// If the session is expired, any associated data should be destroyed.
	// If `max_age=0` the store will not check for expiration of the session.
	get(sid string, max_age time.Duration) !T
	// destroy session data for `sid`
	destroy(sid string) !
	// set session data for `sid`
	set(sid string, val T) !
}

// get data from all sessions, optional to implement
pub fn (mut s Store) all[T]() ![]T {
	return []T{}
}

// clear all session data, optional to implement
pub fn (mut s Store) clear[T]() ! {}
```

Only the `get`, `destroy` and `set` methods are required to implement.

### Session Expire time

The `max_age` argument in `get` can be used to check whether the session is still valid.
The database and memory store both check the expiration time from the time the session data
first inserted. But if `max_age = 0`, the stores will not check for expiration time.

- **`highestTierName: zone`**: The scheduler limits topology constraints to the `zone` level (meaning scheduling considers topology up to the zone level and permits spanning multiple racks within a zone, but not across zones).
- **`highestTierName: rack`**: The scheduler limits topology constraints to the `rack` level (meaning scheduling considers topology up to the rack level, and does not permit spanning across different racks).

### Default Behavior

- If `networkTopology` is not configured, no topology-aware scheduling is applied.
- If `mode: soft` is configured, topology affinity is preferred but no hard boundary is enforced.
- If `mode: hard` is configured, `highestTierAllowed` or `highestTierName` can be used to define the scheduling boundary.

# Implementation

## Overview

This chapter describes the architectural implementation of network topology aware scheduling across multiple Volcano components. The implementation spans four main areas:

1. **API & CRDs**: Introduces new Kubernetes Custom Resource Definitions (HyperNode) and extends existing Volcano Job/PodGroup APIs to support network topology constraints. The HyperNode CRD represents hierarchical performance domains in the cluster, while Job specification is extended with partition policies and network topology constraints.

2. **Admission Webhooks**: Provides validation for the new HyperNode CRD to ensure configuration correctness, including member selector validation and regex pattern verification.

3. **Job Controller**: Extends the Volcano Job Controller to map network topology constraints from Volcano Job specifications to PodGroup specifications. During this process, Pods are automatically labeled with subgroup identifiers based on partition policies, enabling fine-grained scheduling constraints.

4. **Scheduler**: Implements the core scheduling logic with the following key enhancements:
   - **Cache Layer**: Introduces HyperNodeInfo, SubJobInfo structures to represent network topology in the scheduler's object model
   - **Plugin Framework**: Extends the plugin system with new functions for HyperNode gradient organization, HyperNode ordering, SubJob readiness checks, and SubJob ordering
   - **Allocation Logic**: Implements a two-level scheduling strategy that respects both Job-level and SubJob-level network topology constraints, with intelligent HyperNode selection based on tier preferences and resource utilization. Besides, two-level gang scheduling is supported to ensure that both Jobs and SubJobs are scheduled atomically.

The interactions among Volcano components are shown as follow:

