#include <fcntl.h>
#include <stdio.h>
#include <unistd.h>
#include <wasmedge/wasmedge.h>

int main(int argc, const char *const argv[]) {
  /* Turn on the WASI config. */
  WasmEdge_ConfigureContext *ConfCxt = WasmEdge_ConfigureCreate();
  WasmEdge_ConfigureAddHostRegistration(ConfCxt,
                                        WasmEdge_HostRegistration_Wasi);

  /* Create the VM context. */
  WasmEdge_VMContext *VMCxt = WasmEdge_VMCreate(ConfCxt, NULL);
  WasmEdge_ConfigureDelete(ConfCxt);

  /* The environment variables. */
  const char EnvStrs[] = {
      'E', 'N', 'V', '1', '=', 'V', 'A', 'L', '1', '\0',
      // ENV1=VAL1
      'E', 'N', 'V', '2', '=', 'V', 'A', 'L', '2', '\0',
      // ENV2=VAL2
      'E', 'N', 'V', '3', '=', 'V', 'A', 'L', '3', '\0'
      // ENV3=VAL3
  };
  const char *const Envs[] = {&EnvStrs[0], &EnvStrs[10], &EnvStrs[20]};

  /* Redirect stdout to a file */
  int OutFd = open("stdout.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (OutFd < 0) {
    perror("Failed to open stdout.txt");
    return 1;
  }

  /* Set the environment variables and arguments. */
  WasmEdge_ModuleInstanceContext *WasiCxt =
      WasmEdge_VMGetImportModuleContext(VMCxt, WasmEdge_HostRegistration_Wasi);

  /* Initialize WASI with environment variables, arguments, preopens, and fd
     redirection. */
  WasmEdge_ModuleInstanceInitWASIWithFds(WasiCxt, argv, argc, Envs, 3, NULL,
                                         0,            // No preopens
                                         STDIN_FILENO, // fd_in = 0 (stdin)
                                         OutFd, // fd_out = redirect to file
                                         STDERR_FILENO // fd_err = stderr
  );

  /* Instantiate the WASM file. */
  WasmEdge_Result Res;
  Res = WasmEdge_VMLoadWasmFromFile(VMCxt, "wasi_get_env.wasm");
  if (!WasmEdge_ResultOK(Res)) {
    printf("Load WASM failed. Error message: %s\n",
           WasmEdge_ResultGetMessage(Res));
  }
  Res = WasmEdge_VMValidate(VMCxt);
  if (!WasmEdge_ResultOK(Res)) {
    printf("Validate WASM failed. Error message: %s\n",
           WasmEdge_ResultGetMessage(Res));
  }
  Res = WasmEdge_VMInstantiate(VMCxt);
  if (!WasmEdge_ResultOK(Res)) {
    printf("Instantiate WASM failed. Error message: %s\n",
           WasmEdge_ResultGetMessage(Res));
  }

  /* Run the WASM function: print_env. */
  WasmEdge_String FuncName = WasmEdge_StringCreateByCString("print_env");
  Res = WasmEdge_VMExecute(VMCxt, FuncName, NULL, 0, NULL, 0);
  WasmEdge_StringDelete(FuncName);
  if (!WasmEdge_ResultOK(Res)) {
    printf("Execution Failed. Error message: %s\n",
           WasmEdge_ResultGetMessage(Res));
  }

  /* Resources deallocations. */
  close(OutFd);
  WasmEdge_VMDelete(VMCxt);
  return 0;
}

#include "script/fibonacci.h"
#include <chrono>
#include <cstdio>
#include <iostream>
#include <wasmedge/wasmedge.h>

void run_fib_wasm() {
  /* Create the configure context and add the WASI support. */
  /* This step is not necessary unless you need WASI support. */
  WasmEdge_ConfigureContext *ConfCxt = WasmEdge_ConfigureCreate();
  WasmEdge_ConfigureAddHostRegistration(ConfCxt,
                                        WasmEdge_HostRegistration_Wasi);
  /* The configure and store context to the VM creation can be NULL. */
  WasmEdge_VMContext *VMCxt = WasmEdge_VMCreate(ConfCxt, NULL);

  /* The parameters and returns arrays. */
  WasmEdge_Value Params[1] = {WasmEdge_ValueGenI32(32)};
  WasmEdge_Value Returns[1];
  /* Function name. */
  WasmEdge_String FuncName = WasmEdge_StringCreateByCString("fib");
  /* Run the WASM function from a file. */
  WasmEdge_Result Res = WasmEdge_VMRunWasmFromFile(
      VMCxt, "fibonacci.wasm", FuncName, Params, 1, Returns, 1);

  if (WasmEdge_ResultOK(Res)) {
    printf("Get result: %d\n", WasmEdge_ValueGetI32(Returns[0]));
  } else {
    printf("Error message: %s\n", WasmEdge_ResultGetMessage(Res));
  }

  /* Resources deallocations. */
  WasmEdge_VMDelete(VMCxt);
  WasmEdge_ConfigureDelete(ConfCxt);
  WasmEdge_StringDelete(FuncName);
}

void run_fib_native() {
  int32_t Ret = fib(32);
  printf("Get result: %d\n", Ret);
}

int main(int Argc, const char *Argv[]) {
  auto Start = std::chrono::system_clock::now();

  run_fib_native();
  auto Step = std::chrono::system_clock::now();
  std::chrono::duration<double> DiffNative = Step - Start;
  std::cout << "run native fib(32), ints : " << DiffNative.count() << " s\n";

  run_fib_wasm();
  auto End = std::chrono::system_clock::now();
  std::chrono::duration<double> DiffWasm = End - Step;
  std::cout << "run wasm fib(32), ints : " << DiffWasm.count() << " s\n";
  return 0;
}

#include "fibonacci.h"

auto fib(int32_t n) -> int32_t {
  if (n < 2) {
    return 1;
  }
  return fib(n - 2) + fib(n - 1);
}

