    "\x11":     quoted_insert,          /* ^Q - quoted-insert */
    "\x12":     alert,                  /* ^R - reverse-search */
    "\x13":     alert,                  /* ^S - search */
    "\x14":     transpose_chars,        /* ^T - transpose */
    "\x18":     reset,                  /* ^X - cancel */
    "\x19":     yank,                   /* ^Y - yank */
    "\x1bOA":   previous_history,       /* ^[OA - up */
    "\x1bOB":   next_history,           /* ^[OB - down */
    "\x1bOC":   forward_char,           /* ^[OC - right */
    "\x1bOD":   backward_char,          /* ^[OD - left */
