    "\x1bd":    kill_word,              /* M-d - kill_word */
    "\x1bf":    forward_word,           /* M-f - backward_word */
    "\x1bk":    backward_kill_line,     /* M-k - backward_kill_line */
    "\x1bl":    downcase_word,          /* M-l - downcase_word */
    "\x1bt":    transpose_words,        /* M-t - transpose_words */
    "\x1bu":    upcase_word,            /* M-u - upcase_word */
    "\x7f":     backward_delete_char,   /* ^? - delete */
};

function dupstr(str, count) {
    var res = "";
    while (count-- > 0)
        res += str;
    return res;
}

var readline_keys;
var readline_state;
var readline_cb;

function readline_print_prompt()
{
    std.puts(prompt);
    term_cursor_x = ucs_length(prompt) % term_width;
    last_cmd = "";
    last_cursor_pos = 0;
}

function readline_start(defstr, cb) {
    cmd = defstr || "";
    cursor_pos = cmd.length;
    history_index = history.length;
    readline_cb = cb;

    prompt = pstate;

    if (mexpr) {
        prompt += dupstr(" ", plen - prompt.length);
        prompt += ps2;
    } else {
        if (show_time) {
            var t = Math.round(eval_time) + " ";
            eval_time = 0;
            t = dupstr("0", 5 - t.length) + t;
            prompt += t.substring(0, t.length - 4) + "." + t.substring(t.length - 4);
        }
        plen = prompt.length;
        prompt += ps1;
    }
    readline_print_prompt();
    update();
    readline_state = 0;
}

function handle_char(c1) {
    var c;
    c = String.fromCodePoint(c1);
    switch(readline_state) {
    case 0:
        if (c == '\x1b') {  /* '^[' - ESC */
            readline_keys = c;
            readline_state = 1;
        } else {
            handle_key(c);
        }
        break;
    case 1: /* '^[ */
        readline_keys += c;
        if (c == '[') {
            readline_state = 2;
        } else if (c == 'O') {
            readline_state = 3;
        } else {
            handle_key(readline_keys);
            readline_state = 0;
        }
        break;
    case 2: /* '^[[' - CSI */
        readline_keys += c;
        if (!(c == ';' || (c >= '0' && c <= '9'))) {
            handle_key(readline_keys);
            readline_state = 0;
        }
        break;
    case 3: /* '^[O' - ESC2 */
        readline_keys += c;
        handle_key(readline_keys);
        readline_state = 0;
        break;
    }
}

function handle_key(keys) {
    var fun;

    if (quote_flag) {
        if (ucs_length(keys) === 1)
            insert(keys);
        quote_flag = false;
    } else if (fun = commands[keys]) {
        this_fun = fun;
        switch (fun(keys)) {
        case -1:
            readline_cb(cmd);
            return;
        case -2:
            readline_cb(null);
            return;
        case -3:
            /* uninstall a Ctrl-C signal handler */
            os.signal(os.SIGINT, null);
            /* uninstall the stdin read handler */
            os.setReadHandler(term_fd, null);
            return;
        }
        last_fun = this_fun;
    } else if (ucs_length(keys) === 1 && keys >= ' ') {
        insert(keys);
        last_fun = insert;
    } else {
        alert(); /* beep! */
    }

    cursor_pos = (cursor_pos < 0) ? 0 :
        (cursor_pos > cmd.length) ? cmd.length : cursor_pos;
    update();
}

var hex_mode = false;
var eval_mode = "std";

function number_to_string(a, radix) {
    var s;
    if (!isFinite(a)) {
        /* NaN, Infinite */
        return a.toString();
    } else {
        if (a == 0) {
            if (1 / a < 0)
                s = "-0";
            else
                s = "0";
        } else {
            if (radix == 16 && a === Math.floor(a)) {
                var s;
                if (a < 0) {
                    a = -a;
                    s = "-";
                } else {
                    s = "";
                }
                s += "0x" + a.toString(16);
            } else {
                s = a.toString();
            }
        }
        return s;
    }
}

function bigfloat_to_string(a, radix) {
    var s;
    if (!BigFloat.isFinite(a)) {
        /* NaN, Infinite */
        if (eval_mode !== "math") {
            return "BigFloat(" + a.toString() + ")";
        } else {
            return a.toString();
        }
    } else {
        if (a == 0) {
            if (1 / a < 0)
                s = "-0";
            else
                s = "0";
        } else {
            if (radix == 16) {
                var s;
                if (a < 0) {
                    a = -a;
                    s = "-";
                } else {
                    s = "";
                }
                s += "0x" + a.toString(16);
            } else {
                s = a.toString();
            }
        }
        if (typeof a === "bigfloat" && eval_mode !== "math") {
            s += "l";
        } else if (eval_mode !== "std" && s.indexOf(".") < 0 &&
            ((radix == 16 && s.indexOf("p") < 0) ||
             (radix == 10 && s.indexOf("e") < 0))) {
            /* add a decimal point so that the floating point type
               is visible */
            s += ".0";
        }
        return s;
    }
}

function bigint_to_string(a, radix) {
    var s;
    if (radix == 16) {
        var s;
        if (a < 0) {
            a = -a;
            s = "-";
        } else {
            s = "";
        }
        s += "0x" + a.toString(16);
    } else {
        s = a.toString();
    }
    if (eval_mode === "std")
        s += "n";
    return s;
}

function print(a) {
    var stack = [];

    function print_rec(a) {
        var n, i, keys, key, type, s;

        type = typeof(a);
        if (type === "object") {
            if (a === null) {
                std.puts(a);
            } else if (stack.indexOf(a) >= 0) {
                std.puts("[circular]");
            } else if (has_jscalc && (a instanceof Fraction ||
                                    a instanceof Complex ||
                                    a instanceof Mod ||
                                    a instanceof Polynomial ||
                                    a instanceof PolyMod ||
                                    a instanceof RationalFunction ||
                                    a instanceof Series)) {
                std.puts(a.toString());
            } else {
                stack.push(a);
                if (Array.isArray(a)) {
                    n = a.length;
                    std.puts("[ ");
                    for(i = 0; i < n; i++) {
                        if (i !== 0)
                            std.puts(", ");
                        if (i in a) {
                            print_rec(a[i]);
                        } else {
                            std.puts("<empty>");
                        }
                        if (i > 20) {
                            std.puts("...");
                            break;
                        }
                    }
                    std.puts(" ]");
                } else if (Object.__getClass(a) === "RegExp") {
                    std.puts(a.toString());
                } else {
                    keys = Object.keys(a);
                    n = keys.length;
                    std.puts("{ ");
                    for(i = 0; i < n; i++) {
                        if (i !== 0)
                            std.puts(", ");
                        key = keys[i];
                        std.puts(key, ": ");
                        print_rec(a[key]);
                    }
                    std.puts(" }");
                }
                stack.pop(a);
            }
        } else if (type === "string") {
            s = a.__quote();
            if (s.length > 79)
                s = s.substring(0, 75) + "...\"";
            std.puts(s);
        } else if (type === "number") {
            std.puts(number_to_string(a, hex_mode ? 16 : 10));
        } else if (type === "bigint") {
            std.puts(bigint_to_string(a, hex_mode ? 16 : 10));
        } else if (type === "bigfloat") {
            std.puts(bigfloat_to_string(a, hex_mode ? 16 : 10));
        } else if (type === "bigdecimal") {
            std.puts(a.toString() + "m");
        } else if (type === "symbol") {
            std.puts(String(a));
        } else if (type === "function") {
            std.puts("function " + a.name + "()");
        } else {
            std.puts(a);
        }
    }
    print_rec(a);
}

function extract_directive(a) {
    var pos;
    if (a[0] !== '\\')
        return "";
    for (pos = 1; pos < a.length; pos++) {
        if (!is_alpha(a[pos]))
            break;
    }
    return a.substring(1, pos);
}

/* return true if the string after cmd can be evaluated as JS */
function handle_directive(cmd, expr) {
    var param, prec1, expBits1;

    if (cmd === "h" || cmd === "?" || cmd == "help") {
        help();
    } else if (cmd === "load") {
        var filename = expr.substring(cmd.length + 1).trim();
        if (filename.lastIndexOf(".") <= filename.lastIndexOf("/"))
            filename += ".js";
        std.loadScript(filename);
        return false;
    } else if (cmd === "x") {
        hex_mode = true;
    } else if (cmd === "d") {
        hex_mode = false;
    } else if (cmd === "t") {
        show_time = !show_time;
    } else if (has_bignum && cmd === "p") {
        param = expr.substring(cmd.length + 1).trim().split(" ");
        if (param.length === 1 && param[0] === "") {
            std.puts("BigFloat precision=" + prec + " bits (~" +
                      Math.floor(prec / log2_10) +
                      " digits), exponent size=" + expBits + " bits\n");
        } else if (param[0] === "f16") {
            prec = 11;
            expBits = 5;
        } else if (param[0] === "f32") {
            prec = 24;
            expBits = 8;
        } else if (param[0] === "f64") {
            prec = 53;
            expBits = 11;
        } else if (param[0] === "f128") {
            prec = 113;
            expBits = 15;
        } else {
            prec1 = parseInt(param[0]);
            if (param.length >= 2)
                expBits1 = parseInt(param[1]);
            else
                expBits1 = BigFloatEnv.expBitsMax;
            if (Number.isNaN(prec1) ||
                prec1 < BigFloatEnv.precMin ||
                prec1 > BigFloatEnv.precMax) {
                std.puts("Invalid precision\n");
                return false;
            }
            if (Number.isNaN(expBits1) ||
                expBits1 < BigFloatEnv.expBitsMin ||
                expBits1 > BigFloatEnv.expBitsMax) {
                std.puts("Invalid exponent bits\n");
                return false;
            }
            prec = prec1;
            expBits = expBits1;
        }
        return false;
    } else if (has_bignum && cmd === "digits") {
        param = expr.substring(cmd.length + 1).trim();
        prec1 = Math.ceil(parseFloat(param) * log2_10);
        if (prec1 < BigFloatEnv.precMin ||
            prec1 > BigFloatEnv.precMax) {
            std.puts("Invalid precision\n");
            return false;
        }
        prec = prec1;
        expBits = BigFloatEnv.expBitsMax;
        return false;
    } else if (has_bignum && cmd === "mode") {
        param = expr.substring(cmd.length + 1).trim();
        if (param === "") {
            std.puts("Running mode=" + eval_mode + "\n");
        } else if (param === "std" || param === "math") {
            eval_mode = param;
        } else {
            std.puts("Invalid mode\n");
        }
        return false;
    } else if (cmd === "clear") {
        std.puts("\x1b[H\x1b[J");
    } else if (cmd === "q") {
        std.exit(0);
    } else if (has_jscalc && cmd === "a") {
        algebraicMode = true;
    } else if (has_jscalc && cmd === "n") {
        algebraicMode = false;
    } else {
        std.puts("Unknown directive: " + cmd + "\n");
        return false;
    }
    return true;
}

if (config_numcalc) {
    /* called by the GUI */
    g.execCmd = function (cmd) {
        switch(cmd) {
        case "dec":
            hex_mode = false;
            break;
        case "hex":
            hex_mode = true;
            break;
        case "num":
            algebraicMode = false;
            break;
        case "alg":
            algebraicMode = true;
            break;
        }
    }
}

function help() {
    function sel(n) {
        return n ? "*": " ";
    }
    std.puts("\\h          this help\n" +
             "\\x         " + sel(hex_mode) + "hexadecimal number display\n" +
             "\\d         " + sel(!hex_mode) + "decimal number display\n" +
             "\\t         " + sel(show_time) + "toggle timing display\n" +
              "\\clear      clear the terminal\n");
    if (has_jscalc) {
        std.puts("\\a         " + sel(algebraicMode) + "algebraic mode\n" +
                 "\\n         " + sel(!algebraicMode) + "numeric mode\n");
    }
    if (has_bignum) {
        std.puts("\\p [m [e]]  set the BigFloat precision to 'm' bits\n" +
                 "\\digits n   set the BigFloat precision to 'ceil(n*log2(10))' bits\n");
        if (!has_jscalc) {
            std.puts("\\mode [std|math] change the running mode (current = " + eval_mode + ")\n");
        }
    }
    if (!config_numcalc) {
        std.puts("\\q          exit\n");
    }
}

function eval_and_print(expr) {
    var result;

    try {
        if (eval_mode === "math")
            expr = '"use math"; void 0;' + expr;
        var now = (new Date).getTime();
        /* eval as a script */
        result = std.evalScript(expr, { backtrace_barrier: true });
        eval_time = (new Date).getTime() - now;
        std.puts(colors[styles.result]);
        print(result);
        std.puts("\n");
        std.puts(colors.none);
        /* set the last result */
        g._ = result;
    } catch (error) {
        std.puts(colors[styles.error_msg]);
        if (error instanceof Error) {
            console.log(error);
            if (error.stack) {
                std.puts(error.stack);
            }
        } else {
            std.puts("Throw: ");
            console.log(error);
        }
        std.puts(colors.none);
    }
}

function cmd_start() {
    if (!config_numcalc) {
        if (has_jscalc)
            std.puts('QJSCalc - Type "\\h" for help\n');
        else
            std.puts('QuickJS - Type "\\h" for help\n');
    }
    if (has_bignum) {
        log2_10 = Math.log(10) / Math.log(2);
        prec = 113;
        expBits = 15;
        if (has_jscalc) {
            eval_mode = "math";
            /* XXX: numeric mode should always be the default ? */
            g.algebraicMode = config_numcalc;
        }
    }

    cmd_readline_start();
}

function cmd_readline_start() {
    readline_start(dupstr("    ", level), readline_handle_cmd);
}

function readline_handle_cmd(expr) {
    handle_cmd(expr);
    cmd_readline_start();
}

function handle_cmd(expr) {
    var colorstate, cmd;

    if (expr === null) {
        expr = "";
        return;
    }
    if (expr === "?") {
        help();
        return;
    }
    cmd = extract_directive(expr);
    if (cmd.length > 0) {
        if (!handle_directive(cmd, expr))
            return;
        expr = expr.substring(cmd.length + 1);
    }
    if (expr === "")
        return;

    if (mexpr)
        expr = mexpr + '\n' + expr;
    colorstate = colorize_js(expr);
    pstate = colorstate[0];
    level = colorstate[1];
    if (pstate) {
        mexpr = expr;
        return;
    }
    mexpr = "";

    if (has_bignum) {
        BigFloatEnv.setPrec(eval_and_print.bind(null, expr),
                            prec, expBits);
    } else {
        eval_and_print(expr);
    }
    level = 0;

    /* run the garbage collector after each command */
    std.gc();
}

function colorize_js(str) {
    var i, c, start, n = str.length;
    var style, state = "", level = 0;
    var primary, can_regex = 1;
    var r = [];

    function push_state(c) { state += c; }
    function last_state(c) { return state.substring(state.length - 1); }
    function pop_state(c) {
        var c = last_state();
        state = state.substring(0, state.length - 1);
        return c;
    }

        function parse_block_comment() {
            style = 'comment';
            push_state('/');
            for (i++; i < n - 1; i++) {
                if (str[i] == '*' && str[i + 1] == '/') {
                    i += 2;
                    pop_state('/');
                    break;
                }
            }
        }

        function parse_line_comment() {
            style = 'comment';
            for (i++; i < n; i++) {
                if (str[i] == '\n') {
                    break;
                }
            }
        }

        function parse_string(delim) {
            style = 'string';
            push_state(delim);
            while (i < n) {
                c = str[i++];
                if (c == '\n') {
                    style = 'error';
                    continue;
                }
                if (c == '\\') {
                    if (i >= n)
                        break;
                    i++;
                } else
                if (c == delim) {
                    pop_state();
                    break;
                }
            }
        }

        function parse_regex() {
            style = 'regex';
            push_state('/');
            while (i < n) {
                c = str[i++];
                if (c == '\n') {
                    style = 'error';
                    continue;
                }
                if (c == '\\') {
                    if (i < n) {
                        i++;
                    }
                    continue;
                }
                if (last_state() == '[') {
                    if (c == ']') {
                        pop_state()
                    }
                    // ECMA 5: ignore '/' inside char classes
                    continue;
                }
                if (c == '[') {
                    push_state('[');
                    if (str[i] == '[' || str[i] == ']')
                        i++;
                    continue;
                }
                if (c == '/') {
                    pop_state();
                    while (i < n && is_word(str[i]))
                        i++;
                    break;
                }
            }
        }

        function parse_number() {
            style = 'number';
            while (i < n && (is_word(str[i]) || (str[i] == '.' && (i == n - 1 || str[i + 1] != '.')))) {
                i++;
            }
        }

        var js_keywords = "|" +
            "break|case|catch|continue|debugger|default|delete|do|" +
            "else|finally|for|function|if|in|instanceof|new|" +
            "return|switch|this|throw|try|typeof|while|with|" +
            "class|const|enum|import|export|extends|super|" +
            "implements|interface|let|package|private|protected|" +
            "public|static|yield|" +
            "undefined|null|true|false|Infinity|NaN|" +
            "eval|arguments|" +
            "await|";

        var js_no_regex = "|this|super|undefined|null|true|false|Infinity|NaN|arguments|";
        var js_types = "|void|var|";

        function parse_identifier() {
            can_regex = 1;

            while (i < n && is_word(str[i]))
                i++;

            var w = '|' + str.substring(start, i) + '|';

            if (js_keywords.indexOf(w) >= 0) {
                style = 'keyword';
                if (js_no_regex.indexOf(w) >= 0)
                    can_regex = 0;
                return;
            }

            var i1 = i;
            while (i1 < n && str[i1] == ' ')
                i1++;

            if (i1 < n && str[i1] == '(') {
                style = 'function';
                return;
            }

            if (js_types.indexOf(w) >= 0) {
                style = 'type';
                return;
            }

            style = 'identifier';
            can_regex = 0;
        }

        function set_style(from, to) {
            while (r.length < from)
                r.push('default');
            while (r.length < to)
                r.push(style);
        }

        for (i = 0; i < n;) {
            style = null;
            start = i;
            switch (c = str[i++]) {
            case ' ':
            case '\t':
            case '\r':
            case '\n':
                continue;
            case '+':
            case '-':
                if (i < n && str[i] == c) {
                    i++;
                    continue;
                }
                can_regex = 1;
                continue;
            case '/':
                if (i < n && str[i] == '*') { // block comment
                    parse_block_comment();
                    break;
                }
                if (i < n && str[i] == '/') { // line comment
                    parse_line_comment();
                    break;
                }
                if (can_regex) {
                    parse_regex();
                    can_regex = 0;
                    break;
                }
                can_regex = 1;
                continue;
            case '\'':
            case '\"':
            case '`':
                parse_string(c);
                can_regex = 0;
                break;
            case '(':
            case '[':
            case '{':
                can_regex = 1;
                level++;
                push_state(c);
                continue;
            case ')':
            case ']':
            case '}':
                can_regex = 0;
                if (level > 0 && is_balanced(last_state(), c)) {
                    level--;
                    pop_state();
                    continue;
                }
                style = 'error';
                break;
            default:
                if (is_digit(c)) {
                    parse_number();
                    can_regex = 0;
                    break;
                }
                if (is_word(c) || c == '$') {
                    parse_identifier();
                    break;
                }
                can_regex = 1;
                continue;
            }
            if (style)
                set_style(start, i);
        }
        set_style(n, n);
        return [ state, level, r ];
    }

    termInit();

    cmd_start();

})(globalThis);

