pub mod signatures;

pub fn encode<S: AsRef<str>>(s: S) -> Vec<u8> {
    let length = s.as_ref().len() / 2;
    let mut res = Vec::with_capacity(length);
    for i in 0..length {
        let code = &s.as_ref()[i * 2..i * 2 + 2];
        res.push(u8::from_str_radix(code, 16).expect("Unable to cast hex"));
    }
    res
}

pub fn decode(s: Vec<u8>) -> String {
    s.iter()
        .map(|n| format!("{:X}", n))
        .collect::<Vec<String>>()
        .join("")
}

use wasi_crypto_example::{
    decode, encode,
    signatures::{array_output_len, array_output_pull, signature_export, signature_import},
};

fn main() {
    let code = "9D92E9FDCA3DDF2E1DDCA1E3B7A79A250B6E4AFFCABF5F9FF4D960B152AB8300E9EB978BD3DA89C42BBFE5A2C2AEB0AF1DD178FB4BCD0833B587D118F59BBB4D";
    let encoded = encode(code);

    let handle = signature_import("ECDSA_K256_SHA256".into(), &encoded, 0).unwrap();

    let export_sig_handle = signature_export(handle, 0).unwrap();

    let export_sig_size = array_output_len(export_sig_handle).unwrap();

    let mut export_sig: Vec<u8> = vec![0; export_sig_size as usize];
    let _ = array_output_pull(export_sig_handle, &mut export_sig).unwrap();

    assert_eq!(encoded, export_sig);
    dbg!(decode(encoded));
    dbg!(decode(export_sig));
}

#[derive(Debug)]
pub enum Error {
    // i32 is the error code from the WASI-Crypto-Signature plugin
    SignatureImport(i32),
    SignatureExport(i32),
    ArrayOutputLen(i32),
    ArrayOutputPull(i32),
}

mod ffi {

    #[link(wasm_import_module = "wasi_ephemeral_crypto_signatures")]
    extern "C" {
        pub fn signature_import(
            AlgPtr: *const u8,
            AlgLen: u32,
            EncodedPtr: *const u8,
            EncodedLen: u32,
            Encoding: u16,
            SigHandlePtr: *mut u32,
        ) -> i32;
        pub fn signature_export(
            SigHandle: u32,
            Encoding: u32,
            ArrayOutputHandlePtr: *mut u32,
        ) -> i32;
    }

    #[link(wasm_import_module = "wasi_ephemeral_crypto_common")]
    extern "C" {
        pub fn array_output_len(ArrayOutputHandle: u32, SizePtr: *mut u32) -> i32;
        pub fn array_output_pull(
            ArrayOutputHandle: u32,
            BufPtr: *mut u8,
            BufLen: u32,
            SizePtr: *mut u32,
        ) -> i32;
    }
}

pub fn signature_import<S: AsRef<[u8]>>(
    alg: String,
    encoded: S,
    encoding: u16,
) -> Result<u32, Error> {
    let alg_size = alg.len() as u32;
    let encoded_size = encoded.as_ref().len() as u32;
    let mut sig_handle: u32 = 0;
    unsafe {
        let res = ffi::signature_import(
            alg.as_ptr(),
            alg_size,
            encoded.as_ref().as_ptr(),
            encoded_size,
            encoding,
            &mut sig_handle,
        );
        if res == 0 {
            Ok(sig_handle)
        } else {
            Err(Error::SignatureImport(res))
        }
    }
}

pub fn signature_export(sig_handle: u32, encoding: u16) -> Result<u32, Error> {
    let mut output_handle: u32 = 0;
    unsafe {
        let res = ffi::signature_export(sig_handle, encoding as u32, &mut output_handle);
        if res == 0 {
            Ok(output_handle)
        } else {
            Err(Error::SignatureExport(res))
        }
    }
}

pub fn array_output_len(output_handle: u32) -> Result<u32, Error> {
    let mut length: u32 = 0;
    unsafe {
        let res = ffi::array_output_len(output_handle, &mut length);
        if res == 0 {
            Ok(length)
        } else {
            Err(Error::ArrayOutputLen(res))
        }
    }
}

pub fn array_output_pull(output_handle: u32, buf: &mut Vec<u8>) -> Result<u32, Error> {
    let mut length: u32 = 0;
    unsafe {
        let res = ffi::array_output_pull(output_handle, buf.as_mut_ptr(), 64, &mut length);
        if res == 0 {
            Ok(length)
        } else {
            Err(Error::ArrayOutputPull(res))
        }
    }
}

